  { id: "pq_breakthrough", type: "pain_qualifier", category: "timing", en: "Breakthrough pain", fa: "درد ناگهانی بین دوزهای درمان", colloquial_fa: "با اینکه دارو می‌خورم باز یهویی درد می‌گیره، وسط اثر دارو درد برمی‌گرده، با وجود مسکن درد حمله می‌کنه", modifiers: ["Transient exacerbation", "Despite baseline analgesia"] },
  { id: "pq_post_exertional", type: "pain_qualifier", category: "timing", en: "Exertional pain", fa: "درد حین فعالیت و فعالیت‌وابسته", colloquial_fa: "وقتی راه می‌رم درد می‌گیره، موقع کار کردن شروع می‌شه، با فعالیت درد می‌کنه، با بالا رفتن از پله درد می‌گیرم", modifiers: ["Exertional", "Activity-related", "Relieved by rest"] },

  // PAIN ONSET
  { id: "pq_sudden_onset", type: "pain_qualifier", category: "onset", en: "Sudden onset", fa: "شروع ناگهانی", colloquial_fa: "یهویی شروع شد، یک‌دفعه گرفت، ناگهانی درد گرفت، از یه لحظه به بعد شروع شد، بدون مقدمه درد گرفت", modifiers: ["Abrupt", "Acute", "Well-defined onset"] },
  { id: "pq_gradual_onset", type: "pain_qualifier", category: "onset", en: "Gradual onset", fa: "شروع تدریجی", colloquial_fa: "کم‌کم شروع شد، یواش‌یواش درد گرفت، آروم‌آروم زیاد شد، اول کم بود بعد بیشتر شد", modifiers: ["Insidious", "Gradual", "Progressive"] },
  { id: "pq_thunderclap_onset", type: "pain_qualifier", category: "onset", en: "Thunderclap onset", fa: "شروع انفجاری و رعدآسای درد", colloquial_fa: "انگار بمب توی سرم ترکید، یک‌دفعه بدترین سردرد عمرم شروع شد، مثل انفجار بود، درد در چند ثانیه به اوج رسید", modifiers: ["Instantaneous", "Maximal at onset", "Severe"] },
  { id: "pq_traumatic_onset", type: "pain_qualifier", category: "onset", en: "Post-traumatic onset", fa: "شروع پس از ضربه یا آسیب", colloquial_fa: "بعد از ضربه شروع شد، از وقتی زمین خوردم درد می‌کنه، بعد از تصادف درد گرفت، بعد از برخورد شروع شد", modifiers: ["Trauma-related", "Acute", "Temporal association"] },
  { id: "pq_spontaneous_onset", type: "pain_qualifier", category: "onset", en: "Spontaneous onset", fa: "شروع خودبه‌خودی", colloquial_fa: "خودبه‌خود شروع شد، بی‌دلیل درد گرفت، بدون اینکه کاری کنم شروع شد، هیچ ضربه‌ای نخوردم", modifiers: ["Spontaneous", "No identifiable trigger"] },
  { id: "pq_exertional_onset", type: "pain_qualifier", category: "onset", en: "Exertional onset", fa: "شروع درد با فعالیت", colloquial_fa: "موقع دویدن شروع شد، وقتی سنگین کار کردم گرفت، با راه رفتن شروع شد، حین ورزش درد گرفت", modifiers: ["Exertional", "Activity-triggered"] },
  { id: "pq_postprandial_onset", type: "pain_qualifier", category: "onset", en: "Meal-triggered onset", fa: "شروع درد پس از خوردن غذا", colloquial_fa: "بعد غذا شروع می‌شه، با خوردن غذا درد می‌گیره، به محض غذا خوردن شکمم درد می‌کنه", modifiers: ["Meal-triggered", "Postprandial"] },
  { id: "pq_recurrent_onset", type: "pain_qualifier", category: "onset", en: "Recurrent onset after symptom-free intervals", fa: "شروع مجدد پس از فواصل بدون درد", colloquial_fa: "یه مدت خوبم بعد دوباره شروع می‌شه، درد قطع می‌شه و دوباره برمی‌گرده، چند روز خوبم بعد دوباره می‌گیره", modifiers: ["Relapsing", "Intermittent", "Symptom-free intervals"] },

  // AGGRAVATING FACTORS
  { id: "pq_aggr_movement", type: "pain_qualifier", category: "aggravating", en: "Aggravated by movement", fa: "تشدید با حرکت", colloquial_fa: "با حرکت بدتر می‌شه، وقتی تکون می‌خورم درد می‌گیره، راه می‌رم بیشتر درد می‌کنه، با جابه‌جایی بدتره", modifiers: ["Movement-related", "Activity-induced"] },
  { id: "pq_aggr_palpation", type: "pain_qualifier", category: "aggravating", en: "Aggravated by palpation / Pressure", fa: "تشدید با لمس و فشار", colloquial_fa: "وقتی دست می‌زنم درد می‌گیره، فشار می‌دم بدتر می‌شه، با لمس کردن دردش بیشتر می‌شه، نمی‌ذاره معاینه کنم", modifiers: ["Palpation-induced", "Pressure-sensitive"] },
  { id: "pq_aggr_cough", type: "pain_qualifier", category: "aggravating", en: "Aggravated by coughing or sneezing", fa: "تشدید با سرفه و عطسه", colloquial_fa: "با سرفه درد می‌گیره، عطسه می‌کنم تیر می‌کشه، وقتی سرفه می‌کنم شکمم درد می‌گیره، با عطسه بدتر می‌شه", modifiers: ["Cough-induced", "Valsalva-related"] },
  { id: "pq_aggr_inspiration", type: "pain_qualifier", category: "aggravating", en: "Aggravated by deep inspiration", fa: "تشدید با دم عمیق", colloquial_fa: "وقتی نفس عمیق می‌کشم درد می‌گیره، نمی‌تونم نفس عمیق بکشم، با دم درد می‌کنه، نفس که می‌کشم تیر می‌کشه", modifiers: ["Inspiratory", "Pleuritic"] },
  { id: "pq_aggr_exertion", type: "pain_qualifier", category: "aggravating", en: "Aggravated by exertion", fa: "تشدید با فعالیت بدنی", colloquial_fa: "با فعالیت بدتر می‌شه، وقتی راه می‌رم بیشتر درد می‌گیره، موقع بالا رفتن از پله درد می‌کنه، با ورزش بدتر می‌شه", modifiers: ["Exertional", "Activity-related"] },
  { id: "pq_aggr_meals", type: "pain_qualifier", category: "aggravating", en: "Aggravated by meals", fa: "تشدید با غذا خوردن", colloquial_fa: "بعد غذا بدتر می‌شه، هر چی می‌خورم درد می‌گیره، با خوردن غذا معده‌ام می‌سوزه، غذا می‌خورم شکمم می‌پیچه", modifiers: ["Postprandial", "Meal-related"] },
  { id: "pq_aggr_fasting", type: "pain_qualifier", category: "aggravating", en: "Aggravated by fasting", fa: "تشدید با گرسنگی و ناشتا بودن", colloquial_fa: "وقتی چیزی نمی‌خورم بدتر می‌شه، با خالی بودن معده درد می‌گیره، وقتی گرسنه می‌مونم درد دارم", modifiers: ["Fasting-related", "Hunger-related"] },
  { id: "pq_aggr_position", type: "pain_qualifier", category: "aggravating", en: "Aggravated by specific position", fa: "تشدید با وضعیت خاص بدن", colloquial_fa: "وقتی می‌خوابم بدتر می‌شه، به پهلو که می‌خوابم درد می‌گیره، با خم شدن بدتره، وقتی می‌شینم درد می‌کنه", modifiers: ["Positional", "Posture-dependent"] },
  { id: "pq_aggr_supine", type: "pain_qualifier", category: "aggravating", en: "Aggravated by lying supine", fa: "تشدید در حالت طاق‌باز", colloquial_fa: "وقتی صاف به پشت می‌خوابم بدتر می‌شه، طاق‌باز که می‌شم درد می‌گیره، نمی‌تونم به پشت بخوابم", modifiers: ["Supine-related", "Positional"] },
  { id: "pq_aggr_bending", type: "pain_qualifier", category: "aggravating", en: "Aggravated by bending forward", fa: "تشدید با خم شدن به جلو", colloquial_fa: "وقتی دولا می‌شم درد می‌گیره، خم می‌شم بدتر می‌شه، موقع برداشتن چیزی از زمین درد می‌کنه", modifiers: ["Bending-related", "Movement-induced"] },
  { id: "pq_aggr_defecation", type: "pain_qualifier", category: "aggravating", en: "Aggravated by defecation", fa: "تشدید با اجابت مزاج", colloquial_fa: "موقع دستشویی رفتن درد می‌گیره، وقتی زور می‌زنم دردش بیشتر می‌شه، موقع مدفوع کردن تیر می‌کشه", modifiers: ["Defecation-related", "Straining-induced"] },
  { id: "pq_aggr_urination", type: "pain_qualifier", category: "aggravating", en: "Aggravated by urination", fa: "تشدید با ادرار کردن", colloquial_fa: "موقع ادرار درد می‌گیره، وقتی جیش می‌کنم دردش بیشتر می‌شه، با ادرار کردن تیر می‌کشه", modifiers: ["Micturition-related", "Urinary"] },
  { id: "pq_aggr_intercourse", type: "pain_qualifier", category: "aggravating", en: "Aggravated by sexual intercourse", fa: "تشدید با نزدیکی", colloquial_fa: "موقع رابطه درد می‌گیره، با نزدیکی درد دارم، بعد از رابطه دردش بیشتر می‌شه، موقع دخول درد دارم", modifiers: ["Intercourse-related", "Deep or superficial"] },
  { id: "pq_aggr_menses", type: "pain_qualifier", category: "aggravating", en: "Aggravated by menstruation", fa: "تشدید با قاعدگی", colloquial_fa: "موقع پریود درد می‌گیره، با شروع عادت ماهانه بدتر می‌شه، روزهای پریود دردش بیشتره", modifiers: ["Menstrual-related", "Cyclical"] },
  { id: "pq_aggr_cold", type: "pain_qualifier", category: "aggravating", en: "Aggravated by cold exposure", fa: "تشدید با سرما", colloquial_fa: "با سردی بدتر می‌شه، هوای سرد درد رو زیاد می‌کنه، وقتی سردم می‌شه درد می‌گیره", modifiers: ["Cold-triggered", "Temperature-sensitive"] },
  { id: "pq_aggr_heat", type: "pain_qualifier", category: "aggravating", en: "Aggravated by heat", fa: "تشدید با گرما", colloquial_fa: "با گرما بدتر می‌شه، وقتی گرمم می‌شه درد می‌گیره، گرما اذیتم می‌کنه", modifiers: ["Heat-triggered", "Temperature-sensitive"] },
  { id: "pq_aggr_straining", type: "pain_qualifier", category: "aggravating", en: "Aggravated by straining / Valsalva", fa: "تشدید با زور زدن و مانور والسالوا", colloquial_fa: "وقتی زور می‌زنم درد می‌گیره، موقع بلند کردن جسم سنگین بدتر می‌شه، با حبس نفس و فشار آوردن درد می‌کشه", modifiers: ["Valsalva-related", "Straining-induced"] },

  // RELIEVING FACTORS
  { id: "pq_rel_rest", type: "pain_qualifier", category: "relieving", en: "Relieved by rest", fa: "تسکین با استراحت", colloquial_fa: "وقتی دراز می‌کشم بهتر می‌شه، استراحت می‌کنم خوب می‌شه، با نشستن درد کم می‌شه، وقتی تکون نمی‌خورم خوبه", modifiers: ["Rest-responsive", "Activity-related"] },
  { id: "pq_rel_analgesics", type: "pain_qualifier", category: "relieving", en: "Relieved by analgesics", fa: "تسکین با مسکن", colloquial_fa: "با مسکن خوب می‌شه، قرص درد رو کم می‌کنه، آمپول که می‌زنم آروم می‌شه، با داروی ضد درد بهتر می‌شه", modifiers: ["Analgesic-responsive", "Partial or complete relief"] },
  { id: "pq_rel_position", type: "pain_qualifier", category: "relieving", en: "Relieved by positional change", fa: "تسکین با تغییر وضعیت بدن", colloquial_fa: "وقتی تغییر وضعیت می‌دم بهتر می‌شه، به پهلو که می‌خوابم خوب می‌شه، با جمع کردن پاها آروم می‌شه، یه حالت خاص که می‌گیرم درد کم می‌شه", modifiers: ["Positional", "Posture-dependent"] },
  { id: "pq_rel_sitting", type: "pain_qualifier", category: "relieving", en: "Relieved by sitting upright", fa: "تسکین با نشستن و خم شدن به جلو", colloquial_fa: "وقتی می‌شینم بهتر می‌شه، دولا می‌شم آروم می‌گیره، به جلو خم می‌شم درد کم می‌شه، با نشستن راحت‌ترم", modifiers: ["Sitting-responsive", "Forward-leaning"] },
  { id: "pq_rel_food", type: "pain_qualifier", category: "relieving", en: "Relieved by eating", fa: "تسکین با غذا خوردن", colloquial_fa: "وقتی چیزی می‌خورم بهتر می‌شه، با غذا درد معده‌ام می‌خوابه، گرسنگی که رفع می‌شه درد کم می‌شه", modifiers: ["Food-responsive", "Hunger-related"] },
  { id: "pq_rel_antacid", type: "pain_qualifier", category: "relieving", en: "Relieved by antacids", fa: "تسکین با آنتی‌اسید", colloquial_fa: "با شربت معده خوب می‌شه، شربت آلومینیوم می‌خورم آروم می‌شه، با قرص معده سوزشم می‌خوابه، با داروی ضد اسید بهتر می‌شه", modifiers: ["Antacid-responsive", "Acid-related"] },
  { id: "pq_rel_defecation", type: "pain_qualifier", category: "relieving", en: "Relieved by defecation", fa: "تسکین با اجابت مزاج", colloquial_fa: "بعد از دستشویی رفتن خوب می‌شه، وقتی مدفوع می‌کنم شکمم آروم می‌شه، بعد از دفع درد کم می‌شه", modifiers: ["Defecation-responsive", "Bowel-related"] },
  { id: "pq_rel_flatus", type: "pain_qualifier", category: "relieving", en: "Relieved by passing flatus", fa: "تسکین با دفع گاز", colloquial_fa: "وقتی باد شکمم خارج می‌شه خوب می‌شم، باد معده که درمیاد آروم می‌شم، با آروغ یا گاز شکمم سبک می‌شه", modifiers: ["Flatus-responsive", "Bloating-related"] },
  { id: "pq_rel_vomiting", type: "pain_qualifier", category: "relieving", en: "Relieved by vomiting", fa: "تسکین پس از استفراغ", colloquial_fa: "وقتی بالا میارم بهتر می‌شم، بعد از استفراغ درد شکمم کم می‌شه، با تهوع و استفراغ آروم می‌شه", modifiers: ["Vomiting-responsive", "Gastrointestinal"] },
  { id: "pq_rel_urination", type: "pain_qualifier", category: "relieving", en: "Relieved by urination", fa: "تسکین با ادرار کردن", colloquial_fa: "وقتی ادرار می‌کنم بهتر می‌شه، بعد از خالی کردن مثانه درد کم می‌شه، جیش می‌کنم آروم می‌شه", modifiers: ["Micturition-responsive", "Bladder-related"] },
  { id: "pq_rel_warmth", type: "pain_qualifier", category: "relieving", en: "Relieved by warmth / Heat application", fa: "تسکین با گرما", colloquial_fa: "کیسه آب گرم می‌ذارم خوب می‌شه، با حوله گرم آروم می‌شه، گرما درد رو کم می‌کنه، حمام گرم بهترم می‌کنه", modifiers: ["Heat-responsive", "Muscular or cramping"] },
  { id: "pq_rel_cold", type: "pain_qualifier", category: "relieving", en: "Relieved by cold application", fa: "تسکین با سرما", colloquial_fa: "یخ می‌ذارم بهتر می‌شه، با کمپرس سرد دردش کم می‌شه، آب سرد آرومش می‌کنه", modifiers: ["Cold-responsive", "Localized"] },
  { id: "pq_rel_immobilization", type: "pain_qualifier", category: "relieving", en: "Relieved by immobilization", fa: "تسکین با بی‌حرکت نگه داشتن عضو", colloquial_fa: "وقتی دست و پام رو ثابت نگه می‌دارم بهتره، تکونش نمی‌دم درد نمی‌گیره، آتل یا بستن عضو کمک می‌کنه", modifiers: ["Immobilization-responsive", "Movement-related"] },
  { id: "pq_rel_elevation", type: "pain_qualifier", category: "relieving", en: "Relieved by limb elevation", fa: "تسکین با بالا نگه داشتن اندام", colloquial_fa: "وقتی پام رو بالا می‌ذارم بهتر می‌شه، پا رو می‌ذارم روی بالش درد کم می‌شه، با بالا گرفتن دست یا پا خوب می‌شه", modifiers: ["Elevation-responsive", "Limb-related"] },

  // PAIN SEVERITY
  { id: "pq_severity_mild", type: "pain_qualifier", category: "severity", en: "Mild pain", fa: "درد خفیف", colloquial_fa: "یه کم درد دارم، دردش زیاد نیست، قابل تحمله، اذیت می‌کنه ولی می‌تونم کارهامو انجام بدم", modifiers: ["Mild", "NRS 1-3", "Minimal functional impairment"] },
  { id: "pq_severity_moderate", type: "pain_qualifier", category: "severity", en: "Moderate pain", fa: "درد متوسط", colloquial_fa: "دردش متوسطه، اذیتم می‌کنه، به سختی کارهامو انجام می‌دم، نه خیلی کم نه خیلی زیاد", modifiers: ["Moderate", "NRS 4-6", "Partial functional impairment"] },
  { id: "pq_severity_severe", type: "pain_qualifier", category: "severity", en: "Severe pain", fa: "درد شدید", colloquial_fa: "خیلی درد دارم، غیرقابل تحمله، از درد به خودم می‌پیچم، نمی‌تونم تکون بخورم، از شدت درد گریه می‌کنم", modifiers: ["Severe", "NRS 7-10", "Major functional impairment"] },

  // ==================== PART 2: HPI SYMPTOMS ====================

  // GENERAL / CONSTITUTIONAL
  { id: "hpi_fever", type: "hpi_symptom", category: "general", en: "Fever", fa: "تب", colloquial_fa: "تب دارم، بدنم داغ شده، تنم آتیش گرفته، سرما و گرما می‌شم، دمای بدنم بالا رفته، احساس حرارت می‌کنم", modifiers: ["Subjective", "Documented", "Low-grade", "High-grade", "Intermittent", "Persistent", "Remittent", "Relapsing"] },
  { id: "hpi_chills", type: "hpi_symptom", category: "general", en: "Chills", fa: "لرز", colloquial_fa: "لرز دارم، بدنم می‌لرزه، سردم می‌شه، دندونام به هم می‌خوره، از سرما می‌لرزم، پتو می‌خوام", modifiers: ["Mild", "Severe", "With fever", "Without documented fever"] },
  { id: "hpi_rigors", type: "hpi_symptom", category: "general", en: "Rigors", fa: "لرز شدید و تکان‌دهنده", colloquial_fa: "لرز شدید می‌کنم، تمام بدنم می‌لرزه، نمی‌تونم جلوی لرزم رو بگیرم، دندونام محکم به هم می‌خوره، بدنم از لرز تکون می‌خوره", modifiers: ["Shaking", "Severe", "Febrile"] },
  { id: "hpi_fatigue", type: "hpi_symptom", category: "general", en: "Fatigue", fa: "خستگی", colloquial_fa: "زود خسته می‌شم، همش خسته‌ام، انرژی ندارم، جون ندارم، حوصله هیچ کاری رو ندارم، زود از پا می‌افتم", modifiers: ["Mild", "Moderate", "Severe", "Persistent", "Exertional"] },
  { id: "hpi_malaise", type: "hpi_symptom", category: "general", en: "Malaise", fa: "کسالت و ناخوشی عمومی", colloquial_fa: "حالم خوب نیست، یه جور ناخوشی دارم، احساس مریضی می‌کنم، بدنم رو فرم نیست، بی‌حالم، انگار دارم مریض می‌شم", modifiers: ["Generalized", "Acute", "Chronic"] },
  { id: "hpi_weakness_general", type: "hpi_symptom", category: "general", en: "Generalized weakness", fa: "ضعف عمومی", colloquial_fa: "ضعف دارم، بدنم سسته، جون ندارم، دست و پام جون نداره، توان انجام کار ندارم، بی‌رمقم", modifiers: ["Generalized", "Progressive", "Acute", "Chronic"] },
  { id: "hpi_weight_loss", type: "hpi_symptom", category: "general", en: "Unintentional weight loss", fa: "کاهش وزن ناخواسته", colloquial_fa: "لاغر شدم، وزن کم کردم، آب شدم، لباسام برام گشاد شده، بی‌دلیل وزنم پایین اومده، صورتم تکیده شده", modifiers: ["Intentional", "Unintentional", "Rapid", "Gradual", "Quantified", "Unquantified"] },
  { id: "hpi_weight_gain", type: "hpi_symptom", category: "general", en: "Weight gain", fa: "افزایش وزن", colloquial_fa: "چاق شدم، وزنم بالا رفته، سنگین شدم، شکمم اومده جلو، بی‌دلیل وزن اضافه کردم", modifiers: ["Rapid", "Gradual", "Intentional", "Unintentional"] },
  { id: "hpi_night_sweats", type: "hpi_symptom", category: "general", en: "Night sweats", fa: "تعریق شبانه", colloquial_fa: "شب‌ها عرق می‌کنم، از عرق خیس می‌شم، نصف شب لباسم خیسه، عرق سرد می‌کنم، رختخوابم خیس می‌شه", modifiers: ["Mild", "Drenching", "Intermittent", "Persistent"] },
  { id: "hpi_anorexia", type: "hpi_symptom", category: "general", en: "Loss of appetite / Anorexia", fa: "بی‌اشتهایی", colloquial_fa: "اشتها ندارم، میلی به غذا ندارم، غذا از گلوم پایین نمی‌ره، اصلاً گرسنه نمی‌شم، از غذا بدم میاد، غذا نمی‌تونم بخورم", modifiers: ["Partial", "Complete", "Acute", "Chronic"] },
  { id: "hpi_increased_appetite", type: "hpi_symptom", category: "general", en: "Increased appetite / Polyphagia", fa: "افزایش اشتها و پرخوری", colloquial_fa: "همش گرسنه‌ام، سیر نمی‌شم، مدام دلم غذا می‌خواد، هر چی می‌خورم باز گرسنه‌ام", modifiers: ["Persistent", "Episodic", "Associated with weight change"] },
  { id: "hpi_thirst", type: "hpi_symptom", category: "general", en: "Excessive thirst / Polydipsia", fa: "تشنگی زیاد", colloquial_fa: "همش تشنه‌ام، دهنم خشک می‌شه، هر چی آب می‌خورم سیراب نمی‌شم، مدام آب می‌خوام", modifiers: ["Persistent", "Nocturnal", "Associated with polyuria"] },
  { id: "hpi_pruritus_general", type: "hpi_symptom", category: "general", en: "Pruritus", fa: "خارش", colloquial_fa: "خارش دارم، تنم می‌خاره، پوستم می‌خارونه، همه بدنم می‌خاره، مورمور و خارش دارم", modifiers: ["Localized", "Generalized", "Nocturnal", "With rash", "Without rash"] },
  { id: "hpi_sleep_disturbance", type: "hpi_symptom", category: "general", en: "Sleep disturbance", fa: "اختلال خواب", colloquial_fa: "خوابم نمی‌بره، نصف شب بیدار می‌شم، خوابم سبک شده، مدام از خواب می‌پرم، صبح خسته بیدار می‌شم", modifiers: ["Insomnia", "Sleep-maintenance difficulty", "Early-morning awakening", "Non-restorative sleep"] },
  { id: "hpi_dehydration", type: "hpi_symptom", category: "general", en: "Symptoms of dehydration", fa: "علائم کم‌آبی بدن", colloquial_fa: "دهنم خشک شده، خیلی تشنه‌ام، ادرارم کم شده، سرم گیج می‌ره، بدنم بی‌آبه، لبام خشک شده", modifiers: ["Mild", "Moderate", "Severe", "Reduced urine output", "Dry mucosa"] },

  // GASTROINTESTINAL / ABDOMINAL / SURGICAL
  { id: "hpi_abdominal_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Abdominal pain", fa: "درد شکم", colloquial_fa: "دل‌درد، شکمم درد می‌کنه، دلم درد می‌کنه، توی شکمم درد دارم، زیر دلم درد می‌کنه، بالای شکمم درد می‌کنه", modifiers: ["Epigastric", "Periumbilical", "Right upper quadrant", "Left upper quadrant", "Right lower quadrant", "Left lower quadrant", "Suprapubic", "Diffuse", "Localized", "Migratory"] },
  { id: "hpi_epigastric_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Epigastric pain", fa: "درد اپی‌گاستر و سردل", colloquial_fa: "سردلم درد می‌کنه، بالای معده‌ام درد می‌کنه، زیر جناغم درد دارم، سر دل تیر می‌کشه، وسط بالای شکمم درد می‌کنه", modifiers: ["Burning", "Gnawing", "Postprandial", "Fasting-related", "Radiating to back"] },
  { id: "hpi_ruq_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Right upper quadrant pain", fa: "درد ربع فوقانی راست شکم", colloquial_fa: "بالای سمت راست شکمم درد می‌کنه، زیر دنده راست درد دارم، سمت راست بالای شکم تیر می‌کشه، زیر دنده‌هام سمت راست درد می‌کنه", modifiers: ["Localized", "Postprandial", "Radiating to right shoulder", "Colicky", "Persistent"] },
  { id: "hpi_rlq_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Right lower quadrant pain", fa: "درد ربع تحتانی راست شکم", colloquial_fa: "پایین شکمم سمت راست درد می‌کنه، زیر دل راست درد دارم، سمت راست پایین شکمم تیر می‌کشه، نزدیک آپاندیسم درد می‌کنه", modifiers: ["Localized", "Migratory", "Acute", "Progressive"] },
  { id: "hpi_llq_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Left lower quadrant pain", fa: "درد ربع تحتانی چپ شکم", colloquial_fa: "پایین شکمم سمت چپ درد می‌کنه، زیر دل چپ درد دارم، سمت چپ پایین شکمم تیر می‌کشه", modifiers: ["Localized", "Colicky", "Persistent", "Intermittent"] },
  { id: "hpi_periumbilical_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Periumbilical pain", fa: "درد اطراف ناف", colloquial_fa: "دور نافم درد می‌کنه، دور شکمم نزدیک ناف می‌پیچه، اطراف نافم می‌گیره، نافم درد می‌کنه", modifiers: ["Periumbilical", "Migratory", "Colicky", "Diffuse"] },
  { id: "hpi_pelvic_abdominal_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Lower abdominal / Pelvic pain", fa: "درد زیر شکم و لگن", colloquial_fa: "زیر دلم درد می‌کنه، پایین شکمم درد می‌کنه، توی لگنم درد دارم، زیر نافم درد می‌کنه، درد زیر شکمی دارم", modifiers: ["Suprapubic", "Pelvic", "Midline", "Unilateral", "Bilateral"] },
  { id: "hpi_bloating", type: "hpi_symptom", category: "gastrointestinal", en: "Abdominal bloating", fa: "نفخ شکم", colloquial_fa: "شکمم باد کرده، نفخ دارم، شکمم پف کرده، شکمم پر از باده، شکمم باد می‌کنه، احساس پری شکم دارم", modifiers: ["Postprandial", "Persistent", "Intermittent", "Upper abdominal", "Lower abdominal"] },
  { id: "hpi_distension", type: "hpi_symptom", category: "gastrointestinal", en: "Abdominal distension", fa: "اتساع شکم", colloquial_fa: "شکمم بزرگ و بادکرده شده، شکمم اومده جلو، شکمم ورم کرده، شکمم سفت و بزرگ شده، اندازه شکمم زیاد شده", modifiers: ["Progressive", "Acute", "Chronic", "Generalized", "Localized"] },
  { id: "hpi_heartburn", type: "hpi_symptom", category: "gastrointestinal", en: "Heartburn / Pyrosis", fa: "سوزش سردل", colloquial_fa: "ترش کردن، سر دلم می‌سوزه، معده‌ام آتیش گرفته، سوزش از معده تا گلو میاد، آب تلخ میاد تو گلوم، پشت جناغم می‌سوزه", modifiers: ["Postprandial", "Nocturnal", "Positional", "Radiating to throat"] },
  { id: "hpi_regurgitation", type: "hpi_symptom", category: "gastrointestinal", en: "Regurgitation", fa: "برگشت محتویات معده به مری یا دهان", colloquial_fa: "غذا برمی‌گرده تو دهنم، غذا میاد بالا، آب یا غذا برمی‌گرده، بدون اینکه بالا بیارم غذا میاد تو دهنم، ترشی میاد بالا", modifiers: ["Acidic", "Bitter", "Food-containing", "Nocturnal", "Positional"] },
  { id: "hpi_water_brash", type: "hpi_symptom", category: "gastrointestinal", en: "Water brash", fa: "ترشح ناگهانی بزاق در اثر رفلاکس", colloquial_fa: "دهنم پر از آب می‌شه، آب دهنم یک‌دفعه زیاد می‌شه، یه دفعه آب توی دهنم جمع می‌شه، آب دهنم راه می‌افته", modifiers: ["Sudden salivation", "Acid reflux-associated"] },
  { id: "hpi_nausea", type: "hpi_symptom", category: "gastrointestinal", en: "Nausea", fa: "تهوع", colloquial_fa: "حالم به هم می‌خوره، دلم آشوبه، حالت بالا آوردن دارم، دلم می‌خواد استفراغ کنم، احساس تهوع دارم، دلم می‌پیچه و حالم بد می‌شه", modifiers: ["Mild", "Severe", "Persistent", "Intermittent", "Postprandial", "Morning-predominant"] },
  { id: "hpi_vomiting", type: "hpi_symptom", category: "gastrointestinal", en: "Vomiting / Emesis", fa: "استفراغ", colloquial_fa: "بالا میارم، استفراغ می‌کنم، هر چی می‌خورم برمی‌گرده، معده‌ام خالی می‌شه، غذا رو پس می‌زنم، عق می‌زنم و بالا میارم", modifiers: ["Bilious", "Non-bilious", "Food-containing", "Projectile", "Postprandial", "Feculent", "Bloody", "Non-bloody", "Single episode", "Recurrent"] },
  { id: "hpi_dry_heaving", type: "hpi_symptom", category: "gastrointestinal", en: "Retching / Dry heaving", fa: "عق زدن و استفراغ خشک", colloquial_fa: "عق می‌زنم ولی چیزی بالا نمیاد، زور می‌زنم بالا بیارم ولی نمی‌شه، حالت استفراغ دارم اما چیزی خارج نمی‌شه", modifiers: ["Productive", "Non-productive", "Recurrent"] },
  { id: "hpi_hematemesis", type: "hpi_symptom", category: "gastrointestinal", en: "Hematemesis", fa: "استفراغ خونی", colloquial_fa: "خون بالا آوردم، توی استفراغم خون بود، موقع بالا آوردن خون اومد، استفراغم قرمز بود، رگه خون توی بالا آورده‌ام دیدم", modifiers: ["Bright red blood", "Dark blood", "Coffee-ground appearance", "Clots", "Small volume", "Large volume"] },
  { id: "hpi_coffee_ground", type: "hpi_symptom", category: "gastrointestinal", en: "Coffee-ground emesis", fa: "استفراغ شبیه تفاله قهوه", colloquial_fa: "بالا آوردم مثل تفاله قهوه بود، استفراغم قهوه‌ای و دونه‌دونه بود، مثل لرد قهوه، شبیه پودر قهوه خیس", modifiers: ["Dark brown", "Granular", "Altered blood"] },
  { id: "hpi_dysphagia", type: "hpi_symptom", category: "gastrointestinal", en: "Dysphagia", fa: "دیسفاژی؛ اختلال در بلع", colloquial_fa: "غذا توی گلوم گیر می‌کنه، غذا پایین نمی‌ره، موقع قورت دادن مشکل دارم، لقمه گیر می‌کنه، آب هم سخت پایین می‌ره، مجبورم با آب غذا رو قورت بدم", modifiers: ["Oropharyngeal", "Esophageal", "Solids only", "Liquids only", "Solids and liquids", "Progressive", "Intermittent"] },
  { id: "hpi_odynophagia", type: "hpi_symptom", category: "gastrointestinal", en: "Odynophagia", fa: "اودینوفاژی؛ بلع دردناک", colloquial_fa: "وقتی قورت می‌دم درد می‌گیره، بلعیدن درد داره، آب یا غذا که می‌ره پایین گلوم درد می‌کنه، موقع قورت دادن می‌سوزه", modifiers: ["Mild", "Severe", "Solids-related", "Liquids-related"] },
  { id: "hpi_globus", type: "hpi_symptom", category: "gastrointestinal", en: "Globus sensation", fa: "احساس توده در گلو", colloquial_fa: "انگار یه چیزی توی گلوم گیر کرده، بغض دارم، یه تیکه غذا توی گلوم مونده، احساس گلوله توی گلو دارم، چیزی توی گلومه ولی قورت نمی‌ره", modifiers: ["Persistent", "Intermittent", "Non-obstructive"] },
  { id: "hpi_belching", type: "hpi_symptom", category: "gastrointestinal", en: "Belching / Eructation", fa: "آروغ زدن", colloquial_fa: "آروغ می‌زنم، باد از دهنم خارج می‌شه، مدام آروغ دارم، آروغم زیاد شده، آروغ ترش می‌زنم", modifiers: ["Frequent", "Excessive", "Postprandial", "Acidic"] },
  { id: "hpi_flatulence", type: "hpi_symptom", category: "gastrointestinal", en: "Flatulence", fa: "دفع گاز از مقعد", colloquial_fa: "باد شکم دارم، گاز معده خارج می‌شه، زیاد باد روده دارم، شکمم پر از گازه، باد از پایین خارج می‌شه", modifiers: ["Excessive", "Foul-smelling", "Frequent", "Reduced"] },
  { id: "hpi_diarrhea", type: "hpi_symptom", category: "gastrointestinal", en: "Diarrhea", fa: "اسهال", colloquial_fa: "شکم‌روش دارم، شکمم کار می‌کنه، مدفوعم شله، آبکی دستشویی می‌رم، هی باید برم دستشویی، شکمم رفته روی آب، روده‌هام شل شده", modifiers: ["Acute", "Chronic", "Watery", "Mucous", "Bloody", "Small-volume", "Large-volume", "Frequent", "Nocturnal"] },
  { id: "hpi_constipation", type: "hpi_symptom", category: "gastrointestinal", en: "Constipation", fa: "یبوست", colloquial_fa: "یبوست دارم، شکمم کار نمی‌کنه، مدفوعم سفت شده، سخت دستشویی می‌رم، چند روزه شکمم کار نکرده، دفعم سخته، باید زور بزنم", modifiers: ["Acute", "Chronic", "Hard stool", "Infrequent stool", "Straining", "Incomplete evacuation"] },
  { id: "hpi_obstipation", type: "hpi_symptom", category: "gastrointestinal", en: "Obstipation", fa: "عدم دفع مدفوع و گاز", colloquial_fa: "نه مدفوع دارم نه باد شکم خارج می‌شه، شکمم کاملاً بسته، نه دستشویی می‌رم نه باد درمیاد، شکمم از کار افتاده", modifiers: ["No stool", "No flatus", "Acute", "Progressive"] },
  { id: "hpi_tenesmus", type: "hpi_symptom", category: "gastrointestinal", en: "Tenesmus", fa: "تنسموس؛ احساس دفع ناکامل و زورپیچ", colloquial_fa: "زورپیچ، حس می‌کنم شکمم کامل خالی نشده، همش حس دستشویی دارم، می‌رم دستشویی ولی چیزی نمیاد، احساس دفع دارم ولی دفعی انجام نمی‌شه، انگار هنوز مدفوع مونده", modifiers: ["Rectal", "Persistent urge", "Incomplete evacuation", "Painful"] },
  { id: "hpi_hematochezia", type: "hpi_symptom", category: "gastrointestinal", en: "Hematochezia", fa: "هماتوشزی؛ دفع خون قرمز از مقعد", colloquial_fa: "خون روشن موقع دستشویی میاد، روی مدفوع خون می‌بینم، خون از مقعدم میاد، بعد از دفع خون می‌ریزه، خون تازه همراه مدفوع دارم", modifiers: ["Bright red", "Mixed with stool", "On stool surface", "On toilet paper", "Separate from stool", "Small volume", "Large volume", "With clots"] },
  { id: "hpi_melena", type: "hpi_symptom", category: "gastrointestinal", en: "Melena", fa: "ملنا؛ مدفوع سیاه و قیری", colloquial_fa: "مدفوعم سیاه شده، مثل قیر شده، مدفوع سیاه و بدبو دارم، رنگ مدفوعم مثل روغن سوخته است، مدفوع چسبنده و سیاه", modifiers: ["Black", "Tarry", "Foul-smelling", "Sticky", "Recurrent"] },
  { id: "hpi_mucus_stool", type: "hpi_symptom", category: "gastrointestinal", en: "Mucus in stool", fa: "موکوس در مدفوع", colloquial_fa: "لِزج توی مدفوعمه، مخاط دفع می‌کنم، یه چیز لزج همراه مدفوع میاد، مدفوعم کف و لزجی داره، ژله‌ای دفع می‌کنم", modifiers: ["Clear", "White", "Yellow", "Bloody", "Small amount", "Large amount"] },
  { id: "hpi_steatorrhea", type: "hpi_symptom", category: "gastrointestinal", en: "Steatorrhea", fa: "استئاتوره؛ مدفوع چرب", colloquial_fa: "مدفوعم چربه، روی آب می‌مونه، چرب و روغنیه، به کاسه توالت می‌چسبه، شبیه روغن از بدنم خارج می‌شه، مدفوعم برق می‌زنه", modifiers: ["Bulky", "Greasy", "Floating", "Foul-smelling", "Difficult to flush"] },
  { id: "hpi_pale_stool", type: "hpi_symptom", category: "gastrointestinal", en: "Acholic / Pale stool", fa: "مدفوع بی‌رنگ و کم‌رنگ", colloquial_fa: "مدفوعم سفید شده، رنگش مثل گچ شده، خاکستری یا گِلیه، مدفوعم خیلی روشن شده، رنگ طبیعی مدفوع رو نداره", modifiers: ["Clay-colored", "Pale", "Gray", "Persistent"] },
  { id: "hpi_dark_urine", type: "hpi_symptom", category: "gastrointestinal", en: "Dark urine associated with jaundice", fa: "ادرار تیره مرتبط با زردی", colloquial_fa: "ادرارم مثل چای شده، رنگ ادرارم تیره شده، ادرارم قهوه‌ایه، مثل نوشابه تیره است، رنگ ادرارم پررنگ شده", modifiers: ["Tea-colored", "Cola-colored", "Persistent"] },
  { id: "hpi_jaundice", type: "hpi_symptom", category: "gastrointestinal", en: "Jaundice", fa: "یرقان و زردی", colloquial_fa: "زرد شدم، چشمام زرد شده، سفیدی چشمم زرد شده، پوستم زرد شده، رنگم زردی می‌زنه، صورتم زرد شده", modifiers: ["Scleral", "Cutaneous", "Mild", "Marked", "Progressive"] },
  { id: "hpi_pruritus_cholestatic", type: "hpi_symptom", category: "gastrointestinal", en: "Cholestatic pruritus", fa: "خارش مرتبط با کلستاز", colloquial_fa: "وقتی زرد شدم بدنم می‌خاره، خارش شدید بدون جوش دارم، کف دست و پام می‌خاره، همه بدنم می‌خاره", modifiers: ["Generalized", "Palms and soles", "No primary rash", "Nocturnal"] },
  { id: "hpi_early_satiety", type: "hpi_symptom", category: "gastrointestinal", en: "Early satiety", fa: "سیری زودرس", colloquial_fa: "با دو لقمه سیر می‌شم، زود شکمم پر می‌شه، نمی‌تونم زیاد غذا بخورم، یه کم می‌خورم دیگه جا ندارم، اشتهای غذای کامل ندارم", modifiers: ["Mild", "Severe", "Progressive", "Associated with bloating"] },
  { id: "hpi_anorectal_pain", type: "hpi_symptom", category: "gastrointestinal", en: "Anorectal pain", fa: "درد مقعد و ناحیه آنورکتال", colloquial_fa: "مقعدم درد می‌کنه، موقع نشستن درد دارم، ته‌م درد می‌کنه، ناحیه خروج مدفوعم می‌سوزه، اطراف مقعدم درد می‌گیره", modifiers: ["During defecation", "After defecation", "Constant", "Sharp", "Throbbing"] },
  { id: "hpi_anal_itching", type: "hpi_symptom", category: "gastrointestinal", en: "Pruritus ani", fa: "خارش مقعد", colloquial_fa: "مقعدم می‌خاره، دور مقعدم خارش دارم، ته‌م می‌خاره، اطراف سوراخ مقعدم می‌سوزه و می‌خاره", modifiers: ["Nocturnal", "Post-defecation", "Persistent", "With rash"] },
  { id: "hpi_anal_prolapse", type: "hpi_symptom", category: "gastrointestinal", en: "Anal / Rectal prolapse sensation", fa: "بیرون‌زدگی مقعد یا رکتوم", colloquial_fa: "یه چیزی از مقعدم میاد بیرون، موقع دستشویی یه توده بیرون می‌زنه، گوشت اضافه از مقعدم بیرون زده، بعد از دفع باید برش گردونم", modifiers: ["Spontaneously reducible", "Manually reducible", "Irreducible", "Defecation-related"] },
  { id: "hpi_anal_discharge", type: "hpi_symptom", category: "gastrointestinal", en: "Anal discharge", fa: "ترشح از مقعد", colloquial_fa: "از مقعدم ترشح میاد، کنار مقعدم چرک می‌کنه، مایع از ته‌م خارج می‌شه، لباس زیرم از ترشح کثیف می‌شه", modifiers: ["Purulent", "Mucous", "Serous", "Bloody", "Feculent", "Foul-smelling"] },
  { id: "hpi_hemorrhoidal_bulge", type: "hpi_symptom", category: "gastrointestinal", en: "Hemorrhoidal swelling / Lump", fa: "توده یا برجستگی هموروئیدی", colloquial_fa: "بواسیر زدم، گوشت اضافه کنار مقعدم دراومده، یه بادکنک کنار مقعدم هست، موقع دستشویی یه چیزی بیرون می‌زنه", modifiers: ["Internal", "External", "Painful", "Painless", "Bleeding", "Prolapsing"] },
  { id: "hpi_hernia_bulge", type: "hpi_symptom", category: "surgical", en: "Hernial bulge", fa: "برجستگی ناشی از فتق", colloquial_fa: "کشاله رانم باد کرده، نافم بیرون زده، یه برجستگی میاد بیرون، وقتی زور می‌زنم یه توده پیدا می‌شه، وقتی می‌ایستم بیرون می‌زنه، یه ورم میاد و می‌ره", modifiers: ["Reducible", "Irreducible", "Intermittent", "Persistent", "Painful", "Painless", "Cough impulse"] },
  { id: "hpi_abdominal_mass", type: "hpi_symptom", category: "surgical", en: "Abdominal mass / Lump", fa: "توده شکمی", colloquial_fa: "توی شکمم یه توده حس می‌کنم، یه گلوله توی شکمم هست، شکمم یه جا سفت شده، یه برجستگی زیر پوستم حس می‌کنم", modifiers: ["Palpable", "Visible", "Painful", "Painless", "Mobile", "Fixed", "Progressive"] },
  { id: "hpi_hiccups", type: "hpi_symptom", category: "gastrointestinal", en: "Hiccups", fa: "سکسکه", colloquial_fa: "سکسکه می‌کنم، هی هیک می‌کنم، دیافراگمم می‌پره، سکسکه‌ام قطع نمی‌شه", modifiers: ["Transient", "Persistent", "Intractable", "Postprandial"] },
  { id: "hpi_fecal_incontinence", type: "hpi_symptom", category: "gastrointestinal", en: "Fecal incontinence", fa: "بی‌اختیاری مدفوع", colloquial_fa: "مدفوعم بی‌اختیار خارج می‌شه، نمی‌تونم خودمو نگه دارم، قبل از رسیدن به دستشویی کثیف می‌کنم، اختیار شکمم دستم نیست", modifiers: ["Complete", "Partial", "Urgency-associated", "Passive", "Solid stool", "Liquid stool"] },
  { id: "hpi_bowel_habit_change", type: "hpi_symptom", category: "gastrointestinal", en: "Change in bowel habits", fa: "تغییر عادات اجابت مزاج", colloquial_fa: "روال دستشویی رفتنم عوض شده، قبلاً منظم بودم الان نیستم، یه روز اسهالم یه روز یبوست، تعداد دفعات دفعم تغییر کرده", modifiers: ["Frequency increased", "Frequency decreased", "Alternating diarrhea and constipation", "Change in stool consistency", "Change in stool caliber"] },
  { id: "hpi_narrow_stool", type: "hpi_symptom", category: "gastrointestinal", en: "Decreased stool caliber", fa: "کاهش قطر مدفوع", colloquial_fa: "مدفوعم باریک شده، مثل مداد شده، نازک‌تر از قبل دفع می‌کنم، مدفوعم رشته‌ای شده، قطرش کم شده", modifiers: ["Pencil-thin", "Ribbon-like", "Persistent", "New-onset"] },
  { id: "hpi_gastrointestinal_borborygmi", type: "hpi_symptom", category: "gastrointestinal", en: "Borborygmi / Increased bowel sounds", fa: "صدای زیاد روده و شکم", colloquial_fa: "شکمم قاروقور می‌کنه، صدای روده‌هام میاد، شکمم قل‌قل می‌کنه، توی شکمم صدا می‌پیچه", modifiers: ["Frequent", "Postprandial", "With diarrhea", "With bloating"] },
  { id: "hpi_ascites_symptoms", type: "hpi_symptom", category: "gastrointestinal", en: "Symptoms suggestive of ascites", fa: "علائم مرتبط با آسیت", colloquial_fa: "شکمم آب آورده، شکمم هر روز بزرگ‌تر می‌شه، شکمم سنگین شده، توی شکمم مایع جمع شده، زود سیر می‌شم و شکمم باد کرده", modifiers: ["Progressive distension", "Early satiety", "Abdominal heaviness", "Dyspnea"] },

  // CARDIOVASCULAR
  { id: "hpi_chest_pain", type: "hpi_symptom", category: "cardiovascular", en: "Chest pain", fa: "درد قفسه سینه", colloquial_fa: "قفسه سینه‌ام درد می‌کنه، قلبم درد می‌کنه، وسط سینه‌ام درد دارم، زیر جناغم درد می‌کنه، سینه‌ام می‌گیره، توی سینه‌ام فشار دارم", modifiers: ["Retrosternal", "Left-sided", "Right-sided", "Central", "Radiating to arm", "Radiating to jaw", "Radiating to back", "Exertional", "Pleuritic", "Positional"] },
  { id: "hpi_palpitations", type: "hpi_symptom", category: "cardiovascular", en: "Palpitations", fa: "تپش قلب", colloquial_fa: "قلبم تند می‌زنه، قلبم می‌ریزه، قلبم می‌کوبه، احساس می‌کنم قلبم از سینه‌ام بیرون میاد، قلبم نامنظم می‌زنه، یه دفعه قلبم شروع می‌کنه به تند زدن", modifiers: ["Tachycardic", "Bradycardic", "Regular", "Irregular", "Sudden onset", "Sudden termination", "Intermittent", "Persistent"] },
  { id: "hpi_dyspnea", type: "hpi_symptom", category: "cardiovascular", en: "Dyspnea", fa: "تنگی نفس", colloquial_fa: "نفس کم میارم، نفسم بالا نمیاد، نمی‌تونم نفس بکشم، هوا بهم نمی‌رسه، سینه‌ام سنگین می‌شه، احساس خفگی دارم، به زور نفس می‌کشم", modifiers: ["At rest", "On exertion", "Acute", "Chronic", "Progressive", "Intermittent", "Mild", "Severe"] },
  { id: "hpi_orthopnea", type: "hpi_symptom", category: "cardiovascular", en: "Orthopnea", fa: "ارتوپنه؛ تنگی نفس در حالت درازکش", colloquial_fa: "وقتی دراز می‌کشم نفسم می‌گیره، نمی‌تونم صاف بخوابم، باید چند تا بالش زیر سرم بذارم، نشسته بهتر نفس می‌کشم، با خوابیدن خفه می‌شم", modifiers: ["One-pillow", "Two-pillow", "Three-or-more pillows", "Relieved by sitting upright"] },
  { id: "hpi_pnd", type: "hpi_symptom", category: "cardiovascular", en: "Paroxysmal nocturnal dyspnea", fa: "تنگی نفس حمله‌ای شبانه", colloquial_fa: "نصف شب از خفگی بیدار می‌شم، توی خواب نفسم بند میاد، مجبور می‌شم بشینم تا نفسم جا بیاد، شب از خواب می‌پرم و دنبال هوا می‌گردم", modifiers: ["Sudden nocturnal episode", "Sleep-related", "Relieved by sitting upright", "Recurrent"] },
  { id: "hpi_syncope", type: "hpi_symptom", category: "cardiovascular", en: "Syncope", fa: "سنکوپ؛ غش و از دست دادن گذرای هوشیاری", colloquial_fa: "غش کردم، بیهوش شدم، از حال رفتم، چشمام رفت و افتادم، یه لحظه هیچی نفهمیدم، بی‌هوش روی زمین افتادم، از هوش رفتم", modifiers: ["Transient loss of consciousness", "Rapid onset", "Spontaneous recovery", "Prodromal symptoms", "Exertional", "Postural"] },
  { id: "hpi_presyncope", type: "hpi_symptom", category: "cardiovascular", en: "Presyncope", fa: "پیش‌سنکوپ؛ احساس نزدیک به غش", colloquial_fa: "چشمم سیاهی می‌ره، سرم گیج می‌ره، چشام تار می‌شه، حس می‌کنم الان غش می‌کنم، نزدیک بود بیفتم، یه لحظه حس کردم دارم از حال می‌رم، بدنم خالی کرد", modifiers: ["Visual dimming", "Lightheadedness", "Weakness", "Postural", "Prodromal"] },
  { id: "hpi_peripheral_edema", type: "hpi_symptom", category: "cardiovascular", en: "Peripheral edema", fa: "ادم اندام‌های محیطی", colloquial_fa: "پاهام ورم کرده، دست و پام پف کرده، مچ پام باد کرده، جورابم جای عمیق می‌اندازه، وقتی فشار می‌دم جاش می‌مونه، بدنم آب آورده", modifiers: ["Unilateral", "Bilateral", "Pitting", "Non-pitting", "Dependent", "Progressive"] },
  { id: "hpi_cyanosis", type: "hpi_symptom", category: "cardiovascular", en: "Cyanosis", fa: "سیانوز؛ کبودی پوست و مخاط", colloquial_fa: "لبام کبود شده، ناخنام کبود شده، دست و پام آبی شده، رنگ لبم پریده و کبود شده، صورتم کبود می‌زنه", modifiers: ["Central", "Peripheral", "Perioral", "Acute", "Chronic"] },
  { id: "hpi_claudication", type: "hpi_symptom", category: "cardiovascular", en: "Intermittent claudication", fa: "لنگش متناوب عروقی", colloquial_fa: "وقتی راه می‌رم ساق پام درد می‌گیره، بعد از کمی راه رفتن باید وایسم، با استراحت خوب می‌شه و دوباره راه می‌رم درد می‌گیره، موقع پیاده‌روی پام می‌گیره", modifiers: ["Calf", "Thigh", "Buttock", "Fixed walking distance", "Relieved by rest", "Progressive"] },
  { id: "hpi_rest_pain_limb", type: "hpi_symptom", category: "cardiovascular", en: "Ischemic rest pain", fa: "درد ایسکمیک اندام در استراحت", colloquial_fa: "حتی وقتی نشستم پام درد می‌کنه، شب‌ها از درد پا بیدار می‌شم، وقتی پام رو بالا می‌ذارم بدتر می‌شه، مجبورم پام رو از تخت آویزون کنم تا درد کم بشه", modifiers: ["Distal limb", "Nocturnal", "Relieved by dependency", "Severe"] },
  { id: "hpi_cold_extremity", type: "hpi_symptom", category: "cardiovascular", en: "Cold extremity", fa: "سردی اندام", colloquial_fa: "دست و پام همیشه سرده، یه پام از اون یکی سردتره، انگشتام یخ می‌کنه، حتی وقتی هوا گرمه پام سرده", modifiers: ["Unilateral", "Bilateral", "Acute", "Chronic", "Distal"] },
  { id: "hpi_diaphoretic", type: "hpi_symptom", category: "cardiovascular", en: "Diaphoresis", fa: "تعریق شدید", colloquial_fa: "یه دفعه عرق سرد می‌کنم، عرق از سر و صورتم می‌ریزه، بدنم خیس عرق می‌شه، بی‌دلیل عرق می‌کنم", modifiers: ["Cold sweat", "Profuse", "Acute", "Associated with chest pain"] },
  { id: "hpi_chest_tightness", type: "hpi_symptom", category: "cardiovascular", en: "Chest tightness", fa: "احساس گرفتگی قفسه سینه", colloquial_fa: "سینه‌ام می‌گیره، انگار دور سینه‌ام رو بستن، نمی‌تونم سینه‌ام رو باز کنم، احساس فشار و گرفتگی دارم", modifiers: ["Exertional", "At rest", "Intermittent", "Persistent"] },
  { id: "hpi_heart_murmur_awareness", type: "hpi_symptom", category: "cardiovascular", en: "Awareness of heartbeat", fa: "احساس آگاهی از ضربان قلب", colloquial_fa: "ضربان قلبم رو توی سینه‌ام حس می‌کنم، قلبم رو توی گوشم می‌شنوم، حس می‌کنم قلبم محکم می‌کوبه", modifiers: ["At rest", "During exertion", "Nocturnal", "Intermittent"] },

  // RESPIRATORY
  { id: "hpi_cough", type: "hpi_symptom", category: "respiratory", en: "Cough", fa: "سرفه", colloquial_fa: "سرفه می‌کنم، هی سرفه‌ام می‌گیره، گلومم قلقلک می‌شه و سرفه می‌کنم، سرفه‌ام قطع نمی‌شه، سرفه خشک یا خلط‌دار دارم", modifiers: ["Acute", "Subacute", "Chronic", "Dry", "Productive", "Nocturnal", "Paroxysmal", "Barking"] },
  { id: "hpi_dry_cough", type: "hpi_symptom", category: "respiratory", en: "Dry / Non-productive cough", fa: "سرفه خشک", colloquial_fa: "سرفه می‌کنم ولی خلط نداره، سرفه خشک دارم، چیزی از گلوم بالا نمیاد، فقط سرفه می‌کنم، گلومم رو سرفه می‌ندازه", modifiers: ["Acute", "Chronic", "Nocturnal", "Paroxysmal", "Irritative"] },
  { id: "hpi_productive_cough", type: "hpi_symptom", category: "respiratory", en: "Productive cough", fa: "سرفه خلط‌دار", colloquial_fa: "سرفه می‌کنم خلط میاد، سینه‌ام پر از خلطه، خلط بالا میارم، صبح‌ها خلط دارم، سرفه‌ام چرکیه", modifiers: ["Mucoid", "Mucopurulent", "Purulent", "Blood-streaked", "Scanty", "Copious", "Morning-predominant"] },
  { id: "hpi_sputum", type: "hpi_symptom", category: "respiratory", en: "Sputum production", fa: "خلط و خلط‌آوری", colloquial_fa: "خلط دارم، از سینه‌ام خلط میاد، خلط بالا میارم، خلط توی گلوم جمع می‌شه، مجبورم خلط رو بیرون بندازم", modifiers: ["Clear", "White", "Yellow", "Green", "Rust-colored", "Pink frothy", "Bloody", "Foul-smelling", "Thick", "Thin", "Scanty", "Copious"] },
  { id: "hpi_hemoptysis", type: "hpi_symptom", category: "respiratory", en: "Hemoptysis", fa: "هموپتیزی؛ خلط خونی", colloquial_fa: "با سرفه خون میاد، خلط خونی دارم، خون بالا میارم وقتی سرفه می‌کنم، توی خلطم رگه خون هست، خون از ریه‌ام میاد", modifiers: ["Blood-streaked sputum", "Bright red", "Dark red", "Clots", "Scanty", "Moderate", "Massive", "Recurrent"] },
  { id: "hpi_wheezing", type: "hpi_symptom", category: "respiratory", en: "Wheezing", fa: "ویزینگ؛ خس‌خس سینه", colloquial_fa: "سینه‌ام خس‌خس می‌کنه، موقع نفس کشیدن صدا می‌ده، سوت می‌کشه، یه صدای سوت از سینه‌ام میاد، نفس کشیدنم صدا داره", modifiers: ["Expiratory", "Inspiratory", "Biphasic", "Intermittent", "Persistent", "Audible"] },
  { id: "hpi_stridor", type: "hpi_symptom", category: "respiratory", en: "Stridor", fa: "استریدور؛ صدای تنفسی خشن و زیر", colloquial_fa: "موقع نفس کشیدن صدای خشن میاد، گلوم صدا می‌ده، یه صدای سوت خشن از گلو میاد، موقع دم صدا می‌کشم", modifiers: ["Inspiratory", "Expiratory", "Biphasic", "At rest", "With exertion"] },
  { id: "hpi_apnea", type: "hpi_symptom", category: "respiratory", en: "Apnea / Breathing pauses", fa: "آپنه؛ وقفه تنفسی", colloquial_fa: "توی خواب نفسم قطع می‌شه، یه لحظه نفس نمی‌کشم، نفس‌هام می‌ایسته، اطرافیان می‌گن توی خواب نفست بند میاد", modifiers: ["Sleep-related", "Witnessed", "Obstructive pattern", "Central pattern", "Recurrent"] },
  { id: "hpi_snoring", type: "hpi_symptom", category: "respiratory", en: "Snoring", fa: "خرخر شبانه", colloquial_fa: "شب‌ها خر و پف می‌کنم، توی خواب خرخر می‌کنم، موقع خواب صدای نفس کشیدنم بلنده", modifiers: ["Mild", "Loud", "Habitual", "Positional", "Associated with witnessed apnea"] },
  { id: "hpi_hoarseness", type: "hpi_symptom", category: "respiratory", en: "Hoarseness / Dysphonia", fa: "گرفتگی صدا و دیسفونی", colloquial_fa: "صدام گرفته، صدام خش‌دار شده، صدام درنمیاد، صدام دورگه شده، صدام خشن شده، مثل قبل نمی‌تونم حرف بزنم", modifiers: ["Acute", "Chronic", "Intermittent", "Progressive", "After voice use"] },
  { id: "hpi_voice_loss", type: "hpi_symptom", category: "respiratory", en: "Aphonia / Voice loss", fa: "آفونیا؛ از دست دادن صدا", colloquial_fa: "صدام کامل قطع شده، نمی‌تونم حرف بزنم، صدام اصلاً درنمیاد، فقط پچ‌پچ می‌کنم، صدام رو از دست دادم", modifiers: ["Complete", "Partial", "Acute", "Chronic"] },
  { id: "hpi_choking", type: "hpi_symptom", category: "respiratory", en: "Choking sensation", fa: "احساس خفگی", colloquial_fa: "حس خفگی دارم، انگار راه نفسم بسته شده، نمی‌تونم هوا بگیرم، دارم خفه می‌شم، گلومم بسته می‌شه", modifiers: ["Acute", "Intermittent", "Persistent", "During swallowing", "Nocturnal"] },
  { id: "hpi_sputum_foul", type: "hpi_symptom", category: "respiratory", en: "Foul-smelling sputum", fa: "خلط بدبو", colloquial_fa: "خلطم بوی بد می‌ده، خلط گندیده بالا میارم، بوی عفونت می‌ده، خلط بوی تعفن داره", modifiers: ["Persistent", "Intermittent", "Purulent"] },
  { id: "hpi_pleuritic_chest_pain", type: "hpi_symptom", category: "respiratory", en: "Pleuritic chest pain", fa: "درد پلورتیک قفسه سینه", colloquial_fa: "با نفس کشیدن سینه‌ام تیر می‌کشه، با سرفه پهلوم درد می‌گیره، نفس عمیق نمی‌تونم بکشم چون درد می‌گیره", modifiers: ["Inspiratory", "Sharp", "Unilateral", "Cough-associated"] },

  // UROLOGY / NEPHROLOGY
  { id: "hpi_dysuria", type: "hpi_symptom", category: "urologic", en: "Dysuria", fa: "دیس‌اوری؛ ادرار دردناک و سوزش ادرار", colloquial_fa: "موقع جیش سوزش دارم، ادرارم می‌سوزونه، وقتی ادرار می‌کنم درد می‌گیره، راه ادرارم می‌سوزه، جیش کردن درد داره", modifiers: ["Burning", "Painful", "Terminal", "Initial", "Throughout urination"] },
  { id: "hpi_frequency", type: "hpi_symptom", category: "urologic", en: "Urinary frequency", fa: "تکرر ادرار", colloquial_fa: "زیاد جیش می‌کنم، هی دستشویی می‌رم، هر نیم ساعت باید برم دستشویی، دفعات ادرارم زیاد شده، زود به زود ادرار دارم", modifiers: ["Daytime", "Night-time", "Small-volume", "Large-volume", "Acute", "Chronic"] },
  { id: "hpi_urgency", type: "hpi_symptom", category: "urologic", en: "Urinary urgency", fa: "فوریت ادرار", colloquial_fa: "یه دفعه شدیداً جیشم می‌گیره، باید سریع برم دستشویی، نمی‌تونم ادرار رو نگه دارم، تا جیشم می‌گیره باید بدوم دستشویی", modifiers: ["Sudden urge", "Severe", "With urge incontinence", "Without incontinence"] },
  { id: "hpi_nocturia", type: "hpi_symptom", category: "urologic", en: "Nocturia", fa: "شب‌ادراری در بزرگسالان", colloquial_fa: "شب‌ها چند بار برای جیش بیدار می‌شم، نصف شب هی دستشویی می‌رم، خوابم رو برای ادرار قطع می‌کنم", modifiers: ["One episode", "Two episodes", "Three or more episodes", "Chronic"] },
  { id: "hpi_polyuria", type: "hpi_symptom", category: "urologic", en: "Polyuria", fa: "پلی‌اوری؛ افزایش حجم ادرار", colloquial_fa: "ادرارم خیلی زیاد شده، حجم جیشم زیاده، هر بار مقدار زیادی ادرار می‌کنم، شبانه‌روز خیلی ادرار دارم", modifiers: ["Daytime", "Nocturnal", "Persistent", "Associated with polydipsia"] },
  { id: "hpi_oliguria", type: "hpi_symptom", category: "urologic", en: "Oliguria", fa: "الیگوری؛ کاهش حجم ادرار", colloquial_fa: "ادرارم خیلی کم شده، جیشم نمیاد، مقدار ادرارم کم شده، مثل قبل دستشویی نمی‌رم، خیلی کم ادرار می‌کنم", modifiers: ["Acute", "Persistent", "Measured low output", "Associated with edema"] },
  { id: "hpi_anuria", type: "hpi_symptom", category: "urologic", en: "Anuria", fa: "آنوری؛ قطع یا فقدان ادرار", colloquial_fa: "اصلاً جیش نمی‌کنم، ادرارم کامل قطع شده، از صبح تا حالا یه قطره هم ادرار نکردم، هیچ ادراری ندارم", modifiers: ["Complete", "Acute", "Persistent", "Reported or measured"] },
  { id: "hpi_hematuria", type: "hpi_symptom", category: "urologic", en: "Hematuria", fa: "هماچوری؛ وجود خون در ادرار", colloquial_fa: "ادرارم خونی شده، موقع جیش خون میاد، ادرارم قرمزه، خون توی ادرارم دیدم، جیشم صورتی یا قرمز شده", modifiers: ["Gross", "Microscopic", "Initial", "Terminal", "Total", "With clots", "Painless", "Painful"] },
  { id: "hpi_clot_retention", type: "hpi_symptom", category: "urologic", en: "Clot retention", fa: "احتباس ادراری ناشی از لخته", colloquial_fa: "لخته خون توی ادرارم میاد و ادرارم بند میاد، خون لخته شده راه جیش رو می‌بنده، احساس می‌کنم لخته جلوی ادرار رو گرفته", modifiers: ["Visible clots", "Acute retention", "Painful", "Recurrent"] },
  { id: "hpi_hesitancy", type: "hpi_symptom", category: "urologic", en: "Urinary hesitancy", fa: "تأخیر در شروع ادرار", colloquial_fa: "تا می‌رم دستشویی جیشم شروع نمی‌شه، باید صبر کنم تا ادرار بیاد، زور می‌زنم تا جیشم شروع بشه، ادرار دیر راه می‌افته", modifiers: ["Initial", "Intermittent", "Progressive"] },
  { id: "hpi_weak_stream", type: "hpi_symptom", category: "urologic", en: "Weak urinary stream", fa: "ضعف جریان ادرار", colloquial_fa: "فشار جیشم کم شده، ادرارم باریک میاد، مثل قبل با فشار نمیاد، جیشم ضعیف شده، ادرارم شل و بی‌جون میاد", modifiers: ["Weak", "Narrow", "Spraying", "Progressive"] },
  { id: "hpi_intermittency_urine", type: "hpi_symptom", category: "urologic", en: "Urinary intermittency", fa: "قطع و وصل شدن جریان ادرار", colloquial_fa: "جیشم وسطش قطع و وصل می‌شه، پیوسته نمیاد، یه کم میاد بعد می‌ایسته، دوباره باید صبر کنم تا بیاد", modifiers: ["Intermittent stream", "Straining-associated", "Progressive"] },
  { id: "hpi_terminal_dribbling", type: "hpi_symptom", category: "urologic", en: "Terminal dribbling", fa: "چکه‌چکه شدن انتهای ادرار", colloquial_fa: "آخر جیش قطره‌قطره میاد، آخرش چکه می‌کنه، ادرارم تموم نمی‌شه و قطره میاد، ته ادرارم چکه می‌کنه", modifiers: ["Terminal", "Persistent", "Post-micturition"] },
  { id: "hpi_postvoid_dribbling", type: "hpi_symptom", category: "urologic", en: "Post-micturition dribbling", fa: "چکه ادرار پس از اتمام دفع", colloquial_fa: "بعد از اینکه جیشم تموم شد باز چند قطره میاد، از دستشویی که میام بیرون باز ادرار چکه می‌کنه، لباسم بعد از جیش خیس می‌شه", modifiers: ["Post-void", "Delayed", "Persistent"] },
  { id: "hpi_incomplete_emptying", type: "hpi_symptom", category: "urologic", en: "Feeling of incomplete bladder emptying", fa: "احساس تخلیه ناکامل مثانه", colloquial_fa: "حس می‌کنم مثانه‌ام کامل خالی نشده، بعد از جیش هنوز احساس ادرار دارم، انگار یه مقدار جیش مونده، باز دلم می‌خواد دستشویی برم", modifiers: ["Persistent", "Post-void", "With frequency", "With hesitancy"] },
  { id: "hpi_urinary_retention", type: "hpi_symptom", category: "urologic", en: "Urinary retention", fa: "احتباس ادراری", colloquial_fa: "جیشم بند اومده، مثانه‌ام پره ولی ادرار نمیاد، نمی‌تونم ادرار کنم، زیر دلم از ادرار درد گرفته، ادرارم گیر کرده", modifiers: ["Acute", "Chronic", "Complete", "Partial", "Painful", "Painless"] },
  { id: "hpi_stress_incontinence", type: "hpi_symptom", category: "urologic", en: "Stress urinary incontinence", fa: "بی‌اختیاری استرسی ادرار", colloquial_fa: "وقتی سرفه می‌کنم جیشم می‌ریزه، با عطسه ادرارم می‌پره، موقع خندیدن خیس می‌شم، وقتی می‌دوم ادرار خارج می‌شه، با پریدن جیشم می‌ریزه", modifiers: ["Cough-induced", "Sneezing-induced", "Exercise-induced", "Mild", "Severe"] },
  { id: "hpi_urge_incontinence", type: "hpi_symptom", category: "urologic", en: "Urge urinary incontinence", fa: "بی‌اختیاری فوریتی ادرار", colloquial_fa: "تا جیشم می‌گیره نمی‌رسم دستشویی، یه دفعه ادرارم می‌ریزه، نمی‌تونم نگهش دارم، قبل از رسیدن به دستشویی خیس می‌شم", modifiers: ["Urgency-associated", "Small-volume", "Large-volume", "Frequent"] },
  { id: "hpi_overflow_incontinence", type: "hpi_symptom", category: "urologic", en: "Overflow urinary incontinence", fa: "بی‌اختیاری سرریزی ادرار", colloquial_fa: "ادرارم هی قطره‌قطره می‌ریزه، مثانه‌ام انگار پره و سرریز می‌کنه، بدون اینکه بخوام جیش چکه می‌کنه", modifiers: ["Continuous dribbling", "Retention-associated", "Incomplete emptying"] },
  { id: "hpi_continuous_incontinence", type: "hpi_symptom", category: "urologic", en: "Continuous urinary incontinence", fa: "بی‌اختیاری مداوم ادرار", colloquial_fa: "همیشه ادرار ازم می‌ریزه، حتی وقتی دستشویی نمی‌رم لباس زیرم خیسه، کنترل ادرار ندارم و دائم چکه می‌کنه", modifiers: ["Continuous", "Day and night", "Uncontrolled"] },
  { id: "hpi_flank_pain", type: "hpi_symptom", category: "urologic", en: "Flank pain", fa: "درد پهلو", colloquial_fa: "پهلوهام درد می‌کنه، پشت کمرم زیر دنده‌ها درد دارم، پهلوم تیر می‌کشه، یک طرف پشت شکمم درد می‌کنه", modifiers: ["Right", "Left", "Bilateral", "Radiating to groin", "Colicky", "Constant"] },
  { id: "hpi_renal_colic", type: "hpi_symptom", category: "urologic", en: "Renal colic", fa: "کولیک کلیوی", colloquial_fa: "درد وحشتناک پهلو دارم، درد از پهلو می‌زنه به کشاله ران، از درد به خودم می‌پیچم، درد پهلو موجی میاد، بی‌قرارم و نمی‌تونم یه جا بشینم", modifiers: ["Severe", "Colicky", "Radiating to groin", "Restlessness", "Nausea-associated", "Hematuria-associated"] },
  { id: "hpi_suprapubic_pain", type: "hpi_symptom", category: "urologic", en: "Suprapubic pain", fa: "درد سوپراپوبیک و بالای عانه", colloquial_fa: "بالای مثانه‌ام درد می‌کنه، زیر شکمم وسطش درد داره، بالای جای تناسلیم درد می‌کنه، محل مثانه‌ام تیر می‌کشه", modifiers: ["Midline", "Pressure-like", "Micturition-related", "Acute", "Chronic"] },
  { id: "hpi_urethral_discharge", type: "hpi_symptom", category: "urologic", en: "Urethral discharge", fa: "ترشح مجرا", colloquial_fa: "از آلت ترشح میاد، از سوراخ جیشم چرک میاد، صبح‌ها نوک آلتم خیسه، ترشح سفید یا زرد از مجرا دارم", modifiers: ["Purulent", "Mucous", "Clear", "White", "Yellow", "Green", "Bloody", "Spontaneous", "On expression"] },
  { id: "hpi_pneumaturia", type: "hpi_symptom", category: "urologic", en: "Pneumaturia", fa: "پنوماتوری؛ خروج هوا همراه ادرار", colloquial_fa: "موقع جیش حباب هوا میاد، ادرارم کف و حباب داره، انگار باد از مجرای ادرار خارج می‌شه، همراه ادرار گاز میاد", modifiers: ["Intermittent", "Persistent", "Visible bubbles"] },
  { id: "hpi_fecaluria", type: "hpi_symptom", category: "urologic", en: "Fecaluria", fa: "فکالوری؛ وجود مواد مدفوعی در ادرار", colloquial_fa: "توی جیشم ذرات مدفوع می‌بینم، ادرارم بوی مدفوع می‌ده، مثل مدفوع از مجرای ادرارم خارج می‌شه، ادرارم کثیف و قهوه‌ایه", modifiers: ["Visible fecal material", "Foul-smelling", "Persistent", "Intermittent"] },
  { id: "hpi_scrotal_pain", type: "hpi_symptom", category: "urologic", en: "Scrotal pain", fa: "درد اسکروتوم و کیسه بیضه", colloquial_fa: "بیضه‌ام درد می‌کنه، کیسه بیضه‌ام درد گرفته، تخم‌هام درد می‌کنه، درد به کشاله رانم می‌زنه", modifiers: ["Unilateral", "Bilateral", "Acute", "Chronic", "Severe", "Radiating"] },
  { id: "hpi_testicular_swelling", type: "hpi_symptom", category: "urologic", en: "Testicular / Scrotal swelling", fa: "تورم بیضه و کیسه بیضه", colloquial_fa: "بیضه‌ام ورم کرده، کیسه بیضه‌ام بزرگ شده، یکی از بیضه‌هام باد کرده، یه طرف کیسه بیضه‌ام بزرگ‌تر شده", modifiers: ["Unilateral", "Bilateral", "Painful", "Painless", "Acute", "Chronic", "Progressive"] },
  { id: "hpi_penile_pain", type: "hpi_symptom", category: "urologic", en: "Penile pain", fa: "درد آلت تناسلی", colloquial_fa: "آلتم درد می‌کنه، نوک آلتم می‌سوزه، توی آلت درد دارم، موقع نعوظ یا ادرار درد می‌گیره", modifiers: ["Glans", "Shaft", "Urethral", "Erectile", "Micturition-related"] },
  { id: "hpi_erectile_dysfunction", type: "hpi_symptom", category: "urologic", en: "Erectile dysfunction", fa: "اختلال نعوظ", colloquial_fa: "آلتم سفت نمی‌شه، نعوظ ندارم، نعوظم کامل نیست، وسط رابطه شل می‌شه، نمی‌تونم نعوظ رو نگه دارم", modifiers: ["Difficulty initiating", "Difficulty maintaining", "Complete", "Partial", "Situational", "Persistent"] },
  { id: "hpi_hematospermia", type: "hpi_symptom", category: "urologic", en: "Hematospermia", fa: "هماتواسپرمی؛ خون در مایع منی", colloquial_fa: "توی منی‌ام خون هست، منی‌ام قرمز یا قهوه‌ای شده، موقع انزال خون میاد، آب منی‌ام خونی شده", modifiers: ["Bright red", "Brown", "Recurrent", "Single episode", "Painful ejaculation"] },
  { id: "hpi_dyspareunia_male", type: "hpi_symptom", category: "urologic", en: "Painful ejaculation", fa: "انزال دردناک", colloquial_fa: "موقع ارضا شدن درد دارم، وقتی منی خارج می‌شه درد می‌گیره، بعد از انزال آلت یا زیر شکمم درد می‌کنه", modifiers: ["During ejaculation", "After ejaculation", "Perineal", "Urethral", "Pelvic"] },

  // GYNECOLOGY / OBSTETRICS
  { id: "hpi_amenorrhea", type: "hpi_symptom", category: "gynecologic", en: "Amenorrhea", fa: "آمنوره؛ قطع قاعدگی", colloquial_fa: "پریود نمی‌شم، عادت ماهانه‌ام قطع شده، چند ماهه پریود نشدم، پریودم عقب افتاده، دیگه خونریزی ماهانه ندارم", modifiers: ["Primary", "Secondary", "Pregnancy-related", "Postpartum", "Lactational"] },
  { id: "hpi_oligomenorrhea", type: "hpi_symptom", category: "gynecologic", en: "Oligomenorrhea", fa: "الیگومنوره؛ قاعدگی با فواصل طولانی", colloquial_fa: "پریودم دیر به دیر میاد، فاصله پریودهام زیاده، هر چند ماه یه بار پریود می‌شم، سیکلم نامنظمه و طولانیه", modifiers: ["Cycle interval prolonged", "Irregular", "Chronic"] },
  { id: "hpi_polymenorrhea", type: "hpi_symptom", category: "gynecologic", en: "Polymenorrhea", fa: "پلی‌منوره؛ قاعدگی با فواصل کوتاه", colloquial_fa: "زود به زود پریود می‌شم، هنوز یک ماه نشده دوباره پریود می‌شم، فاصله پریودهام کم شده", modifiers: ["Frequent cycles", "Regular", "Irregular"] },
  { id: "hpi_menorrhagia", type: "hpi_symptom", category: "gynecologic", en: "Heavy menstrual bleeding / Menorrhagia", fa: "خونریزی شدید قاعدگی", colloquial_fa: "پریودم خیلی سنگینه، خونریزی‌ام خیلی زیاده، پد یا نوارم زود پر می‌شه، لخته‌های بزرگ دفع می‌کنم، خونریزی‌ام بند نمیاد، مجبورم هر ساعت نوار عوض کنم", modifiers: ["Heavy flow", "Prolonged", "Clots", "Frequent pad changes", "Anemia-associated"] },
  { id: "hpi_hypomenorrhea", type: "hpi_symptom", category: "gynecologic", en: "Hypomenorrhea", fa: "هایپومنوره؛ کاهش حجم خونریزی قاعدگی", colloquial_fa: "پریودم خیلی کم شده، فقط لکه‌بینی دارم، خونریزی‌ام مثل قبل نیست، دو سه قطره خون میاد، پریودم خیلی سبک شده", modifiers: ["Scanty", "Short duration", "Reduced flow"] },
  { id: "hpi_dysmenorrhea", type: "hpi_symptom", category: "gynecologic", en: "Dysmenorrhea", fa: "دیسمنوره؛ قاعدگی دردناک", colloquial_fa: "دوران پریود دل‌درد دارم، زیر دلم می‌پیچه، موقع پریود از درد جمع می‌شم، کمرم موقع عادت ماهانه درد می‌کنه، درد قاعدگی دارم", modifiers: ["Primary", "Secondary", "Cramping", "Mild", "Moderate", "Severe", "Progressive"] },
  { id: "hpi_metrorrhagia", type: "hpi_symptom", category: "gynecologic", en: "Metrorrhagia", fa: "متروراژی؛ خونریزی نامنظم بین قاعدگی‌ها", colloquial_fa: "بین دو تا پریود خونریزی دارم، وسط ماه خون می‌بینم، خارج از زمان پریود خون میاد، بی‌موقع لکه‌بینی می‌کنم", modifiers: ["Intermenstrual", "Irregular", "Scanty", "Heavy"] },
  { id: "hpi_spotting", type: "hpi_symptom", category: "gynecologic", en: "Vaginal spotting", fa: "لکه‌بینی واژینال", colloquial_fa: "لکه خون می‌بینم، فقط چند قطره خون میاد، لباس زیرم لک شده، خونریزی خیلی کم دارم، در حد لکه است", modifiers: ["Pre-menstrual", "Post-menstrual", "Intermenstrual", "Postcoital", "Pregnancy-associated"] },
  { id: "hpi_postcoital_bleeding", type: "hpi_symptom", category: "gynecologic", en: "Postcoital bleeding", fa: "خونریزی پس از نزدیکی", colloquial_fa: "بعد از رابطه خون میاد، موقع نزدیکی خونریزی می‌کنم، بعد از دخول لکه خون می‌بینم، بعد از رابطه لباس یا ملحفه خونی می‌شه", modifiers: ["Scanty", "Heavy", "Recurrent", "Pain-associated"] },
  { id: "hpi_postmenopausal_bleeding", type: "hpi_symptom", category: "gynecologic", en: "Postmenopausal bleeding", fa: "خونریزی پس از یائسگی", colloquial_fa: "بعد از اینکه یائسه شدم دوباره خون دیدم، چند ساله پریود نمی‌شم ولی خونریزی دارم، بعد از قطع پریود لکه‌بینی کردم", modifiers: ["Spotting", "Scanty", "Heavy", "Single episode", "Recurrent"] },
  { id: "hpi_vaginal_discharge", type: "hpi_symptom", category: "gynecologic", en: "Vaginal discharge / Leukorrhea", fa: "ترشح واژینال و لکوره", colloquial_fa: "ترشح دارم، از واژنم آب میاد، لباس زیرم خیس می‌شه، ترشحاتم زیاد شده، ترشح سفید یا زرد دارم، لک دارم", modifiers: ["Clear", "White", "Yellow", "Green", "Gray", "Thick", "Thin", "Curdy", "Frothy", "Foul-smelling", "Physiologic"] },
  { id: "hpi_vaginal_pruritus", type: "hpi_symptom", category: "gynecologic", en: "Vulvovaginal pruritus", fa: "خارش واژن و فرج", colloquial_fa: "واژنم می‌خاره، ناحیه تناسلیم خارش داره، اطراف واژنم می‌سوزه و می‌خاره، داخل و بیرون واژنم می‌خاره", modifiers: ["External", "Internal", "Mild", "Severe", "With discharge", "Without discharge"] },
  { id: "hpi_vulvar_burning", type: "hpi_symptom", category: "gynecologic", en: "Vulvar burning", fa: "سوزش فرج", colloquial_fa: "ناحیه تناسلیم می‌سوزه، بیرون واژنم سوزش داره، وقتی ادرار به پوستم می‌خوره می‌سوزه، پوست اون ناحیه تحریک شده", modifiers: ["Localized", "Diffuse", "Micturition-associated", "Contact-related"] },
  { id: "hpi_dyspareunia", type: "hpi_symptom", category: "gynecologic", en: "Dyspareunia", fa: "دیس‌پارونیا؛ درد هنگام نزدیکی", colloquial_fa: "موقع رابطه درد دارم، نزدیکی برام دردناکه، موقع دخول می‌سوزه، رابطه جنسی اذیتم می‌کنه، بعد از رابطه درد می‌گیرم", modifiers: ["Superficial", "Deep", "Entry-related", "Positional", "During intercourse", "After intercourse"] },
  { id: "hpi_pelvic_pain", type: "hpi_symptom", category: "gynecologic", en: "Pelvic pain", fa: "درد لگنی", colloquial_fa: "توی لگنم درد دارم، زیر شکمم درد می‌کنه، پایین شکمم و اطراف رحم درد می‌کنه، درد داخل لگن دارم", modifiers: ["Acute", "Chronic", "Cyclical", "Unilateral", "Bilateral", "Midline"] },
  { id: "hpi_vaginal_dryness", type: "hpi_symptom", category: "gynecologic", en: "Vaginal dryness", fa: "خشکی واژن", colloquial_fa: "واژنم خشکه، موقع نزدیکی خشکی دارم، ترشح طبیعی ندارم، احساس خشکی و سایش دارم", modifiers: ["Mild", "Severe", "Postmenopausal", "Intercourse-related"] },
  { id: "hpi_vaginal_mass", type: "hpi_symptom", category: "gynecologic", en: "Vaginal / Vulvar mass", fa: "توده واژینال یا ولو", colloquial_fa: "یه برجستگی کنار واژنم دراومده، یه گلوله کنار ناحیه تناسلیم حس می‌کنم، پایین واژنم یه توده هست، گوشت اضافه دراومده", modifiers: ["Painful", "Painless", "Unilateral", "Bilateral", "Fluctuant", "Solid"] },
  { id: "hpi_vaginal_prolapse", type: "hpi_symptom", category: "gynecologic", en: "Pelvic organ prolapse symptoms", fa: "علائم پرولاپس ارگان‌های لگنی", colloquial_fa: "احساس می‌کنم رحمم پایین اومده، یه چیزی از واژنم بیرون زده، توی واژنم یه توده حس می‌کنم، انگار چیزی داره می‌افته پایین، فشار و سنگینی زیر شکم دارم", modifiers: ["Uterine", "Anterior compartment", "Posterior compartment", "Vaginal bulge", "Reducible", "Urinary symptoms"] },
  { id: "hpi_breast_pain", type: "hpi_symptom", category: "gynecologic", en: "Mastalgia", fa: "ماستالژی؛ درد پستان", colloquial_fa: "سینه‌هام درد می‌کنه، پستانم تیر می‌کشه، موقع لمس سینه درد دارم، سینه‌هام حساس شده، قبل پریود سینه‌هام درد می‌گیره", modifiers: ["Unilateral", "Bilateral", "Cyclical", "Non-cyclical", "Focal", "Diffuse"] },
  { id: "hpi_breast_lump", type: "hpi_symptom", category: "gynecologic", en: "Breast lump", fa: "توده پستان", colloquial_fa: "توی سینه‌ام یه گلوله حس می‌کنم، یه توده توی پستانم پیدا کردم، سینه‌ام یه جا سفت شده، یه برجستگی توی سینه‌ام هست", modifiers: ["Unilateral", "Bilateral", "Painful", "Painless", "Mobile", "Fixed", "Progressive"] },
  { id: "hpi_nipple_discharge", type: "hpi_symptom", category: "gynecologic", en: "Nipple discharge", fa: "ترشح از نوک پستان", colloquial_fa: "از نوک سینه‌ام مایع میاد، نوک پستانم ترشح داره، وقتی فشار می‌دم شیر یا مایع خارج می‌شه، از سینه‌ام خون میاد", modifiers: ["Milky", "Clear", "Serous", "Green", "Purulent", "Bloody", "Unilateral", "Bilateral", "Spontaneous", "Expressed"] },
  { id: "hpi_galactorrhea", type: "hpi_symptom", category: "gynecologic", en: "Galactorrhea", fa: "گالاکتوره؛ ترشح شیر خارج از شیردهی", colloquial_fa: "از سینه‌ام شیر میاد در حالی که باردار یا شیرده نیستم، نوک سینه‌ام شیر می‌ده، با فشار مایع شیری خارج می‌شه", modifiers: ["Unilateral", "Bilateral", "Spontaneous", "Expressed"] },
  { id: "hpi_amniotic_fluid_leakage", type: "hpi_symptom", category: "gynecologic", en: "Leakage of amniotic fluid", fa: "نشت مایع آمنیوتیک و پارگی کیسه آب", colloquial_fa: "کیسه آبم پاره شده، از واژنم آب میاد، یه دفعه مایع زیادی خارج شد، لباس زیرم با مایع شفاف خیس شده، آب ازم راه افتاده", modifiers: ["Sudden gush", "Continuous trickle", "Intermittent leakage", "Clear", "Meconium-stained", "Blood-stained"] },
  { id: "hpi_uterine_contractions", type: "hpi_symptom", category: "gynecologic", en: "Uterine contractions", fa: "انقباضات رحمی و دردهای زایمانی", colloquial_fa: "درد زایمان دارم، شکمم سفت می‌شه و ول می‌کنه، دردها منظم میان، شکمم جمع می‌شه، هر چند دقیقه درد می‌گیرم", modifiers: ["Regular", "Irregular", "Increasing frequency", "Increasing intensity", "Painful", "Painless"] },
  { id: "hpi_decreased_fetal_movement", type: "hpi_symptom", category: "gynecologic", en: "Decreased fetal movement", fa: "کاهش حرکات جنین", colloquial_fa: "بچه کمتر تکون می‌خوره، امروز جنینم کم حرکت کرده، مثل قبل لگد نمی‌زنه، حرکت بچه رو حس نمی‌کنم، بچه آروم شده", modifiers: ["Reduced frequency", "Absent movement", "Acute change", "Gradual change"] },

  // NEUROLOGY
  { id: "hpi_headache", type: "hpi_symptom", category: "neurologic", en: "Headache", fa: "سردرد", colloquial_fa: "سرم درد می‌کنه، سرم سنگینه، شقیقه‌هام درد می‌کنه، پیشونیم درد می‌کنه، پشت سرم درد می‌کنه، سرم می‌ترکه، دور سرم می‌پیچه", modifiers: ["Frontal", "Temporal", "Occipital", "Parietal", "Diffuse", "Unilateral", "Bilateral", "Throbbing", "Pressure-like", "Morning-predominant", "Progressive"] },
  { id: "hpi_migraine_like", type: "hpi_symptom", category: "neurologic", en: "Migraine-like headache", fa: "سردرد با الگوی میگرنی", colloquial_fa: "نصف سرم می‌زنه، یه طرف سرم نبض می‌زنه، با نور اذیت می‌شم، با صدا سردردم بدتر می‌شه، با تهوع سردرد می‌گیرم", modifiers: ["Unilateral", "Throbbing", "Nausea-associated", "Photophobia", "Phonophobia", "Aura"] },
  { id: "hpi_dizziness", type: "hpi_symptom", category: "neurologic", en: "Dizziness", fa: "سرگیجه", colloquial_fa: "سرم گیج می‌ره، سرم سبک شده، تعادلم رو از دست می‌دم، احساس منگی دارم، انگار سرم خالی می‌شه، دور سرم می‌چرخه", modifiers: ["Vertigo", "Presyncope", "Disequilibrium", "Lightheadedness", "Unspecified"] },
  { id: "hpi_vertigo", type: "hpi_symptom", category: "neurologic", en: "Vertigo", fa: "ورتیگو؛ احساس چرخش", colloquial_fa: "همه‌چی دور سرم می‌چرخه، اتاق دور سرم می‌چرخه، خودم دارم می‌چرخم، انگار روی کشتی‌ام، زمین زیر پام می‌چرخه، سرم دور می‌گیره", modifiers: ["Rotational", "Subjective", "Objective", "Positional", "Episodic", "Persistent", "With nausea"] },
  { id: "hpi_imbalance", type: "hpi_symptom", category: "neurologic", en: "Disequilibrium / Imbalance", fa: "اختلال تعادل", colloquial_fa: "تعادلم خوب نیست، موقع راه رفتن تلوتلو می‌خورم، انگار به یه طرف کشیده می‌شم، نمی‌تونم صاف راه برم، پام رو درست نمی‌تونم بذارم", modifiers: ["Gait-related", "Standing-related", "Unilateral tendency", "Progressive"] },
  { id: "hpi_gait_disturbance", type: "hpi_symptom", category: "neurologic", en: "Gait disturbance", fa: "اختلال راه رفتن", colloquial_fa: "راه رفتنم عوض شده، درست نمی‌تونم راه برم، پام رو می‌کشم، موقع راه رفتن تلوتلو می‌خورم، پاهایم روی زمین می‌کشه، لنگ می‌زنم", modifiers: ["Ataxic", "Antalgic", "Spastic", "Shuffling", "Steppage", "Unsteady", "Progressive"] },
  { id: "hpi_weakness_focal", type: "hpi_symptom", category: "neurologic", en: "Focal limb weakness", fa: "ضعف موضعی اندام", colloquial_fa: "دستم جون نداره، پام سست شده، یه طرف بدنم ضعیف شده، نمی‌تونم دستم رو بالا بیارم، پام رو نمی‌تونم درست حرکت بدم، زورم کم شده", modifiers: ["Right", "Left", "Upper limb", "Lower limb", "Proximal", "Distal", "Sudden", "Progressive"] },
  { id: "hpi_hemiparesis", type: "hpi_symptom", category: "neurologic", en: "Hemiparesis", fa: "همی‌پارزی؛ ضعف یک نیمه بدن", colloquial_fa: "یه طرف بدنم ضعیف شده، دست و پام از یه سمت جون نداره، سمت راست یا چپم ضعیف شده، یه طرف بدنم خوب حرکت نمی‌کنه", modifiers: ["Right-sided", "Left-sided", "Acute", "Progressive", "Upper and lower limb"] },
  { id: "hpi_paralysis", type: "hpi_symptom", category: "neurologic", en: "Paralysis / Plegia", fa: "فلج اندام", colloquial_fa: "دستم یا پام کامل از کار افتاده، نمی‌تونم تکونش بدم، یه طرفم فلج شده، هیچ حرکتی نمی‌تونم انجام بدم", modifiers: ["Monoplegia", "Hemiplegia", "Paraplegia", "Quadriplegia", "Complete", "Incomplete"] },
  { id: "hpi_numbness", type: "hpi_symptom", category: "neurologic", en: "Numbness", fa: "بی‌حسی", colloquial_fa: "دستم خواب می‌ره، پام بی‌حس می‌شه، چیزی رو لمس می‌کنم حس نمی‌کنم، حس پوستم کم شده، انگار عضو بی‌حسه، پوستش مرده", modifiers: ["Unilateral", "Bilateral", "Focal", "Distal", "Dermatomal", "Persistent", "Intermittent"] },
  { id: "hpi_paresthesia", type: "hpi_symptom", category: "neurologic", en: "Paresthesia", fa: "پارستزی؛ گزگز و مورمور", colloquial_fa: "دستم گزگز می‌کنه، مورمور می‌شه، انگار مورچه روی پوستم راه می‌ره، سوزن‌سوزن می‌شه، خواب می‌ره، سوزن توی دست و پام می‌زنن", modifiers: ["Tingling", "Pins-and-needles", "Burning", "Unilateral", "Bilateral", "Distal"] },
  { id: "hpi_dysesthesia", type: "hpi_symptom", category: "neurologic", en: "Dysesthesia", fa: "دیس‌استزی؛ احساس غیرطبیعی ناخوشایند", colloquial_fa: "لمسش می‌کنم حس بدی می‌ده، پوست بدنم حس عجیبی داره، تماس لباس آزارم می‌ده، حس سوختگی یا برق‌گرفتگی بی‌دلیل دارم", modifiers: ["Burning", "Painful", "Touch-evoked", "Spontaneous"] },
  { id: "hpi_tremor", type: "hpi_symptom", category: "neurologic", en: "Tremor", fa: "ترمور؛ لرزش غیرارادی", colloquial_fa: "دستم می‌لرزه، بدنم می‌لرزه، نمی‌تونم دستم رو ثابت نگه دارم، موقع کار دستم می‌لرزه، سرم می‌لرزه", modifiers: ["Resting", "Postural", "Action", "Intention", "Fine", "Coarse", "Unilateral", "Bilateral"] },
  { id: "hpi_seizure", type: "hpi_symptom", category: "neurologic", en: "Seizure", fa: "تشنج", colloquial_fa: "تشنج کردم، بدنم شروع کرد به لرزیدن، دست و پام جمع شد، کف از دهنم اومد، چشمام برگشت، یه دفعه افتادم و تکون می‌خوردم", modifiers: ["Generalized", "Focal", "Tonic", "Clonic", "Tonic-clonic", "Myoclonic", "Absence", "With loss of consciousness", "Without loss of consciousness"] },
  { id: "hpi_loss_of_consciousness", type: "hpi_symptom", category: "neurologic", en: "Loss of consciousness", fa: "از دست دادن هوشیاری", colloquial_fa: "بیهوش شدم، هیچی نفهمیدم، از حال رفتم، یه مدت بی‌خبر بودم، چشم باز کردم دیدم روی زمینم", modifiers: ["Transient", "Prolonged", "Complete", "Partial", "Witnessed", "Unwitnessed"] },
  { id: "hpi_confusion", type: "hpi_symptom", category: "neurologic", en: "Confusion", fa: "گیجی و اختلال وضعیت ذهنی", colloquial_fa: "قاتی کردم، نمی‌دونم کجام، حواسم جمع نیست، حرف‌ها رو درست متوجه نمی‌شم، گیج و منگم، زمان و مکان رو گم می‌کنم", modifiers: ["Acute", "Chronic", "Fluctuating", "Disorientation to time", "Disorientation to place", "Disorientation to person"] },
  { id: "hpi_memory_loss", type: "hpi_symptom", category: "neurologic", en: "Memory impairment", fa: "اختلال حافظه", colloquial_fa: "حافظه‌ام ضعیف شده، همه‌چی یادم می‌ره، اسم‌ها یادم نمی‌مونه، کارهام رو فراموش می‌کنم، چیزها رو قاطی می‌کنم", modifiers: ["Short-term", "Long-term", "Recent", "Remote", "Progressive", "Intermittent"] },
  { id: "hpi_aphasia", type: "hpi_symptom", category: "neurologic", en: "Aphasia", fa: "آفازی؛ اختلال زبان", colloquial_fa: "کلمه‌ها یادم نمیاد، نمی‌تونم منظورم رو بگم، حرف می‌زنم ولی کلمه پیدا نمی‌کنم، نمی‌تونم حرف دیگران رو بفهمم، زبانم بند اومده", modifiers: ["Expressive", "Receptive", "Global", "Anomic", "Sudden onset"] },
  { id: "hpi_dysarthria", type: "hpi_symptom", category: "neurologic", en: "Dysarthria", fa: "دیس‌آرتری؛ اختلال در تلفظ و ادای کلمات", colloquial_fa: "حرف زدنم نامفهوم شده، زبونم می‌چرخه، کلمات رو درست ادا نمی‌کنم، مثل مست‌ها حرف می‌زنم، دهنم خوب کار نمی‌کنه", modifiers: ["Slurred speech", "Imprecise articulation", "Slow speech", "Acute", "Progressive"] },
  { id: "hpi_diplopia", type: "hpi_symptom", category: "neurologic", en: "Diplopia", fa: "دوبینی", colloquial_fa: "دوتا می‌بینم، تصویرها دو تا می‌شن، نوشته‌ها دوتا دیده می‌شن، وقتی نگاه می‌کنم دو تا تصویر می‌بینم، چشمم دوبل می‌بینه", modifiers: ["Monocular", "Binocular", "Horizontal", "Vertical", "Oblique", "Intermittent", "Persistent"] },
  { id: "hpi_blurred_vision", type: "hpi_symptom", category: "neurologic", en: "Blurred vision", fa: "تاری دید", colloquial_fa: "چشمام تار می‌بینه، همه‌چی مات شده، نوشته‌ها واضح نیستن، دیدم کم‌وضوح شده، مثل بخار جلوی چشممه", modifiers: ["Unilateral", "Bilateral", "Sudden", "Gradual", "Intermittent", "Persistent"] },
  { id: "hpi_visual_loss", type: "hpi_symptom", category: "neurologic", en: "Visual loss", fa: "کاهش یا فقدان بینایی", colloquial_fa: "چشمم نمی‌بینه، یه چشمم کور شده، دیدم کم شده، یه قسمت از دیدم رفته، جلوی چشمم سیاه شده", modifiers: ["Monocular", "Binocular", "Partial", "Complete", "Sudden", "Gradual", "Transient", "Persistent"] },
  { id: "hpi_visual_floaters", type: "hpi_symptom", category: "neurologic", en: "Visual floaters", fa: "مگس‌پران و فلوتر چشمی", colloquial_fa: "جلوی چشمم نقطه‌های سیاه شناور می‌بینم، مگس جلوی چشممه، لکه‌های ریز حرکت می‌کنن، تارهای شناور می‌بینم", modifiers: ["Unilateral", "Bilateral", "New-onset", "Chronic", "Increasing"] },
  { id: "hpi_photopsia", type: "hpi_symptom", category: "neurologic", en: "Photopsia / Flashes of light", fa: "فتوپسی؛ دیدن جرقه نور", colloquial_fa: "جلوی چشمم جرقه می‌زنه، نورهای برق‌آسا می‌بینم، یه دفعه نور می‌پره جلوی چشمم، چشمم برق می‌زنه", modifiers: ["Unilateral", "Bilateral", "Peripheral", "Central", "New-onset"] },
  { id: "hpi_photophobia", type: "hpi_symptom", category: "neurologic", en: "Photophobia", fa: "فوتوفوبیا؛ حساسیت به نور", colloquial_fa: "چشمم به نور حساس شده، نور اذیتم می‌کنه، نمی‌تونم به چراغ نگاه کنم، نور که می‌خوره چشمم درد می‌گیره، باید توی تاریکی باشم", modifiers: ["Mild", "Severe", "Unilateral", "Bilateral", "Headache-associated"] },
  { id: "hpi_phonophobia", type: "hpi_symptom", category: "neurologic", en: "Phonophobia", fa: "فونوفوبیا؛ حساسیت به صدا", colloquial_fa: "صدا اذیتم می‌کنه، تحمل سروصدا رو ندارم، صداهای معمولی هم سرم رو درد میاره، باید همه ساکت باشن", modifiers: ["Mild", "Severe", "Headache-associated"] },
  { id: "hpi_ptosis", type: "hpi_symptom", category: "neurologic", en: "Ptosis", fa: "پتوز؛ افتادگی پلک", colloquial_fa: "پلکم افتاده، چشمم نیمه‌بازه، یکی از پلکام پایین‌تره، نمی‌تونم چشمم رو کامل باز کنم", modifiers: ["Unilateral", "Bilateral", "Complete", "Partial", "Fluctuating"] },
  { id: "hpi_facial_droop", type: "hpi_symptom", category: "neurologic", en: "Facial droop", fa: "افتادگی یک طرف صورت", colloquial_fa: "دهنم کج شده، یه طرف صورتم افتاده، لبم یه طرف می‌ره، وقتی می‌خندم صورتم کجه، صورتم قرینه نیست", modifiers: ["Right-sided", "Left-sided", "Upper face", "Lower face", "Acute"] },
  { id: "hpi_dysphagia_neuro", type: "hpi_symptom", category: "neurologic", en: "Neurologic dysphagia", fa: "اختلال بلع با منشأ عصبی", colloquial_fa: "آب می‌خورم می‌پره توی گلوم، موقع قورت دادن خفه می‌شم، غذا توی دهنم می‌مونه، نمی‌تونم درست قورت بدم، موقع خوردن سرفه می‌کنم", modifiers: ["Oropharyngeal", "Liquids", "Solids", "Aspiration symptoms", "Cough-associated"] },
  { id: "hpi_neck_stiffness", type: "hpi_symptom", category: "neurologic", en: "Neck stiffness", fa: "خشکی و سفتی گردن", colloquial_fa: "گردنم خشکه، نمی‌تونم سرم رو خم کنم، گردنم سفت شده، چونه‌ام به سینه‌ام نمی‌رسه، موقع خم کردن گردن درد می‌گیره", modifiers: ["Painful", "Painless", "Acute", "Chronic", "Limited range of motion"] },
  { id: "hpi_back_pain", type: "hpi_symptom", category: "neurologic", en: "Back pain", fa: "کمردرد و درد پشت", colloquial_fa: "کمرم درد می‌کنه، پشتم گرفته، پایین کمرم درد داره، کمرم تیر می‌کشه، از کمرم درد می‌زنه به پام", modifiers: ["Cervical", "Thoracic", "Lumbar", "Sacral", "Radicular", "Axial", "Acute", "Chronic"] },
  { id: "hpi_radicular_pain", type: "hpi_symptom", category: "neurologic", en: "Radicular pain / Sciatica", fa: "درد رادیکولار و سیاتیک", colloquial_fa: "درد از کمرم می‌زنه توی پام، سیاتیک دارم، پشت پام تیر می‌کشه، از باسنم تا ساق پام درد می‌ره، درد تا انگشت پام می‌رسه", modifiers: ["Right-sided", "Left-sided", "Bilateral", "Dermatomal", "Below knee", "With numbness", "With weakness"] },
  { id: "hpi_saddle_anesthesia", type: "hpi_symptom", category: "neurologic", en: "Saddle anesthesia", fa: "بی‌حسی ناحیه زینی", colloquial_fa: "اطراف مقعدم بی‌حس شده، بین پاهام حس ندارم، موقع پاک کردن بعد دستشویی حس نمی‌کنم، ناحیه تناسلی و بین ران‌هام خواب رفته", modifiers: ["Perineal", "Perianal", "Genital", "Acute", "Progressive"] },
  { id: "hpi_bladder_bowel_neuro", type: "hpi_symptom", category: "neurologic", en: "New bladder or bowel dysfunction", fa: "اختلال جدید ادرار یا اجابت مزاج با احتمال منشأ عصبی", colloquial_fa: "کنترل ادرارم از دستم در رفته، مدفوعم بی‌اختیار خارج می‌شه، نمی‌تونم جیشم رو نگه دارم، دفعم رو حس نمی‌کنم، تازه دچار مشکل ادرار و مدفوع شدم", modifiers: ["Urinary retention", "Urinary incontinence", "Fecal incontinence", "Reduced perineal sensation", "Acute onset"] },
  { id: "hpi_myoclonus", type: "hpi_symptom", category: "neurologic", en: "Myoclonus", fa: "میوکلونوس؛ پرش ناگهانی عضله", colloquial_fa: "عضله‌ام یه دفعه می‌پره، دست یا پام ناگهانی تکون می‌خوره، بدنم پرش‌های کوتاه داره، موقع خواب بدنم می‌پره", modifiers: ["Focal", "Multifocal", "Generalized", "Sleep-related", "Action-induced"] },
  { id: "hpi_fasciculation", type: "hpi_symptom", category: "neurologic", en: "Fasciculation", fa: "فاسیکولاسیون؛ پرش ریز عضله", colloquial_fa: "زیر پوستم عضله می‌پره، یه قسمت از بدنم خودش تکون می‌خوره، گوشت بدنم می‌لرزه، بدون اینکه بخوام یه عضله ریز می‌پره", modifiers: ["Localized", "Multifocal", "Persistent", "Intermittent"] },

  // TRAUMA / MUSCULOSKELETAL / EXTREMITY
  { id: "hpi_trauma_pain", type: "hpi_symptom", category: "trauma", en: "Post-traumatic pain", fa: "درد پس از تروما", colloquial_fa: "بعد از ضربه درد می‌کنه، زمین خوردم و درد گرفتم، بعد تصادف درد دارم، از وقتی ضربه خوردم این قسمت درد می‌کنه", modifiers: ["Immediate onset", "Delayed onset", "Localized", "Diffuse", "Progressive"] },
  { id: "hpi_swelling", type: "hpi_symptom", category: "trauma", en: "Swelling", fa: "تورم", colloquial_fa: "ورم کرده، باد کرده، پف کرده، بزرگ شده، یه قسمت بدنم متورم شده، حجمش زیاد شده", modifiers: ["Localized", "Diffuse", "Unilateral", "Bilateral", "Pitting", "Non-pitting", "Acute", "Chronic"] },
  { id: "hpi_bruising", type: "hpi_symptom", category: "trauma", en: "Bruising / Ecchymosis", fa: "کبودی و اکیموز", colloquial_fa: "کبود شده، جاش سیاه و آبی شده، زیر پوستم خون مردگی افتاده، پوستش بنفش شده، یه جای بدنم رنگ عوض کرده", modifiers: ["Small", "Large", "Expanding", "Spontaneous", "Post-traumatic", "Multiple"] },
  { id: "hpi_hematoma", type: "hpi_symptom", category: "trauma", en: "Hematoma", fa: "هماتوم؛ تجمع خون در بافت", colloquial_fa: "زیر پوستم خون جمع شده، یه ورم پر از خون دارم، جای ضربه باد کرده و سفت شده، یه گلوله خون زیر پوستم هست", modifiers: ["Localized", "Expanding", "Painful", "Fluctuant", "Post-traumatic"] },
  { id: "hpi_deformity", type: "hpi_symptom", category: "trauma", en: "Deformity", fa: "دفورمیتی؛ تغییر شکل اندام", colloquial_fa: "دستم کج شده، پام شکلش عوض شده، استخونم بیرون زده، عضو از حالت طبیعی خارج شده، یه برآمدگی غیرعادی پیدا کرده", modifiers: ["Visible", "Palpable", "Acute", "Chronic", "Rotational", "Angulated"] },
  { id: "hpi_limb_immobility", type: "hpi_symptom", category: "trauma", en: "Inability to move limb", fa: "ناتوانی در حرکت دادن اندام", colloquial_fa: "نمی‌تونم دستم رو تکون بدم، پام حرکت نمی‌کنه، از درد نمی‌تونم عضوم رو حرکت بدم، دستم قفل شده", modifiers: ["Pain-limited", "Motor deficit", "Complete", "Partial", "Acute"] },
  { id: "hpi_reduced_rom", type: "hpi_symptom", category: "trauma", en: "Reduced range of motion", fa: "محدودیت دامنه حرکتی", colloquial_fa: "عضوم مثل قبل خم و راست نمی‌شه، نمی‌تونم کامل دستم رو بالا ببرم، زانوم تا آخر خم نمی‌شه، حرکت مفصلم محدود شده", modifiers: ["Active", "Passive", "Painful", "Painless", "Mild", "Severe"] },
  { id: "hpi_inability_bear_weight", type: "hpi_symptom", category: "trauma", en: "Inability to bear weight", fa: "ناتوانی در تحمل وزن", colloquial_fa: "نمی‌تونم روی پام وایسم، نمی‌تونم وزنم رو روی این پا بندازم، پام رو زمین می‌ذارم درد می‌گیره، نمی‌تونم راه برم", modifiers: ["Complete", "Partial", "Pain-related", "Immediate post-trauma"] },
  { id: "hpi_limping", type: "hpi_symptom", category: "trauma", en: "Limping", fa: "لنگیدن", colloquial_fa: "لنگ می‌زنم، یه پام رو می‌کشم، موقع راه رفتن یه طرفم رو کمتر می‌ذارم، نمی‌تونم درست قدم بردارم", modifiers: ["Antalgic", "Unilateral", "Bilateral", "Acute", "Chronic"] },
  { id: "hpi_open_wound", type: "hpi_symptom", category: "trauma", en: "Open wound", fa: "زخم باز", colloquial_fa: "پوستم شکافته، بدنم زخم شده، یه جای پوستم باز شده، گوشت بدنم معلومه، پوست پاره شده", modifiers: ["Superficial", "Deep", "Clean", "Contaminated", "Bleeding", "Non-bleeding"] },
  { id: "hpi_laceration", type: "hpi_symptom", category: "trauma", en: "Laceration", fa: "لاسراسیون؛ زخم بریدگی و پارگی", colloquial_fa: "پوستم بریده، جای چاقو یا شیشه بریده، پوست پاره شده، یه بریدگی عمیق دارم، زخمم بازه", modifiers: ["Linear", "Irregular", "Superficial", "Deep", "Bleeding", "Gaping"] },
  { id: "hpi_abrasion", type: "hpi_symptom", category: "trauma", en: "Abrasion", fa: "ابریژن؛ خراشیدگی پوست", colloquial_fa: "پوستم ساییده شده، زمین خوردم پوستم رفت، پوست دست و پام خراشیده، زخم سطحی و ساییدگی دارم", modifiers: ["Superficial", "Localized", "Extensive", "Contaminated"] },
  { id: "hpi_puncture_wound", type: "hpi_symptom", category: "trauma", en: "Puncture wound", fa: "زخم سوراخ‌شونده", colloquial_fa: "چیزی توی پام فرو رفته، میخ توی پام رفته، زخم سوراخی دارم، با سوزن یا جسم نوک‌تیز سوراخ شده", modifiers: ["Superficial", "Deep", "Retained foreign body", "Contaminated"] },
  { id: "hpi_burn", type: "hpi_symptom", category: "trauma", en: "Burn injury", fa: "سوختگی", colloquial_fa: "پوستم سوخته، آب جوش روم ریخته، با آتیش سوختم، جای سوختگی دارم، پوستم تاول زده، پوست کنده شده", modifiers: ["Thermal", "Chemical", "Electrical", "Superficial", "Partial-thickness", "Full-thickness", "Blistering"] },
  { id: "hpi_foreign_body_sensation", type: "hpi_symptom", category: "trauma", en: "Foreign body sensation", fa: "احساس وجود جسم خارجی", colloquial_fa: "انگار یه چیزی توی پوستم مونده، شیشه یا خار توی دستمه، چیزی توی چشمم گیر کرده، حس می‌کنم یه جسم توی بدنمه", modifiers: ["Eye", "Skin", "Soft tissue", "Superficial", "Deep"] },
  { id: "hpi_bleeding_external", type: "hpi_symptom", category: "trauma", en: "External bleeding", fa: "خونریزی خارجی", colloquial_fa: "خون میاد، خونریزی دارم، زخمم خون می‌ده، خون بند نمیاد، از جای ضربه خون می‌ریزه", modifiers: ["Arterial-appearing", "Venous-appearing", "Capillary", "Active", "Intermittent", "Controlled", "Uncontrolled"] },
  { id: "hpi_head_trauma", type: "hpi_symptom", category: "trauma", en: "Head injury symptoms", fa: "علائم پس از ضربه به سر", colloquial_fa: "سرم ضربه خورده، بعد از ضربه سرم گیج می‌ره، سرم درد می‌کنه، بعد زمین خوردن حالم بد شده، بعد تصادف سرم سنگین شده", modifiers: ["Headache", "Dizziness", "Nausea", "Vomiting", "Loss of consciousness", "Amnesia", "Confusion"] },
  { id: "hpi_post_traumatic_amnesia", type: "hpi_symptom", category: "trauma", en: "Post-traumatic amnesia", fa: "فراموشی پس از ضربه", colloquial_fa: "یادم نمیاد چی شد، لحظه تصادف رو یادم نیست، بعد از ضربه یه مدت رو یادم نمیاد، نمی‌دونم چطور افتادم", modifiers: ["Retrograde", "Anterograde", "Transient", "Persistent"] },
  { id: "hpi_bite_wound", type: "hpi_symptom", category: "trauma", en: "Bite wound", fa: "زخم ناشی از گازگرفتگی", colloquial_fa: "سگ گازم گرفته، گربه گازم گرفته، جای دندون روی پوستم مونده، حیوان دستم رو گاز گرفته", modifiers: ["Dog bite", "Cat bite", "Human bite", "Superficial", "Deep", "Bleeding", "Infected"] },
  { id: "hpi_joint_locking", type: "hpi_symptom", category: "trauma", en: "Joint locking", fa: "قفل‌شدگی مفصل", colloquial_fa: "زانوم قفل می‌کنه، مفصلم گیر می‌کنه، یه دفعه نمی‌تونم زانوم رو باز کنم، پام توی یه وضعیت گیر می‌کنه", modifiers: ["True locking", "Intermittent", "Painful", "Knee", "Other joint"] },
  { id: "hpi_joint_instability", type: "hpi_symptom", category: "trauma", en: "Joint instability", fa: "ناپایداری مفصل", colloquial_fa: "زانوم خالی می‌کنه، پام زیرم می‌پیچه، مفصلم ول می‌کنه، موقع راه رفتن حس می‌کنم مفصلم از جا درمیاد", modifiers: ["Giving way", "Recurrent", "Traumatic", "Weight-bearing related"] },

  // POSTOPERATIVE / SURGICAL WOUND
  { id: "hpi_postop_wound_pain", type: "hpi_symptom", category: "postoperative_wound", en: "Postoperative wound pain", fa: "درد محل زخم جراحی", colloquial_fa: "جای بخیه‌هام درد می‌کنه، محل عملم درد داره، زخم جراحی‌ام می‌سوزه، اطراف برش جراحی درد می‌گیره، جای عملم می‌کشه", modifiers: ["Mild", "Moderate", "Severe", "Increasing", "Decreasing", "At rest", "On movement"] },
  { id: "hpi_wound_redness", type: "hpi_symptom", category: "postoperative_wound", en: "Wound redness / Erythema", fa: "قرمزی محل زخم", colloquial_fa: "دور بخیه قرمز شده، اطراف زخم سرخ شده، پوست دور محل عمل قرمزه، قرمزی زخم بیشتر شده", modifiers: ["Localized", "Spreading", "Mild", "Marked", "Warm-associated"] },
  { id: "hpi_wound_warmth", type: "hpi_symptom", category: "postoperative_wound", en: "Wound warmth", fa: "گرمی محل زخم", colloquial_fa: "جای بخیه داغه، دور زخم گرم شده، محل عمل از بقیه پوست گرم‌تره، وقتی دست می‌زنم گرما حس می‌کنم", modifiers: ["Localized", "Diffuse", "With erythema", "Without erythema"] },
  { id: "hpi_wound_swelling", type: "hpi_symptom", category: "postoperative_wound", en: "Wound swelling", fa: "تورم محل زخم", colloquial_fa: "جای عملم ورم کرده، دور بخیه باد کرده، محل برش پف کرده، زیر زخم یه برجستگی پیدا شده", modifiers: ["Localized", "Diffuse", "Fluctuant", "Firm", "Progressive"] },
  { id: "hpi_wound_discharge", type: "hpi_symptom", category: "postoperative_wound", en: "Wound discharge", fa: "ترشح از زخم جراحی", colloquial_fa: "از بخیه‌هام مایع میاد، زخمم ترشح داره، جای عملم خیس می‌شه، از محل برش آب یا چرک خارج می‌شه، پانسمانم خیس می‌شه", modifiers: ["Serous", "Sanguineous", "Serosanguineous", "Purulent", "Feculent", "Bilious", "Clear", "Yellow", "Green", "Foul-smelling"] },
  { id: "hpi_wound_serous", type: "hpi_symptom", category: "postoperative_wound", en: "Serous wound discharge", fa: "ترشح سروزی زخم", colloquial_fa: "از زخمم آب شفاف میاد، مایع زرد کم‌رنگ و رقیق خارج می‌شه، زخمم آب می‌اندازه، ترشح آبکی دارم", modifiers: ["Clear", "Straw-colored", "Thin", "Scanty", "Copious"] },
  { id: "hpi_wound_sanguineous", type: "hpi_symptom", category: "postoperative_wound", en: "Sanguineous wound discharge", fa: "ترشح خونی زخم", colloquial_fa: "از بخیه خون میاد، محل عمل خون‌آبه یا خون می‌ده، پانسمانم خونی می‌شه، زخمم خونریزی می‌کنه", modifiers: ["Bright red", "Dark red", "Fresh blood", "Scanty", "Copious"] },
  { id: "hpi_wound_serosanguineous", type: "hpi_symptom", category: "postoperative_wound", en: "Serosanguineous wound discharge", fa: "ترشح سروسانگوینوس زخم", colloquial_fa: "از زخمم مایع صورتی میاد، آب مخلوط با خون خارج می‌شه، ترشح رقیق صورتی‌رنگ دارم، پانسمانم صورتی و خیس می‌شه", modifiers: ["Pink", "Thin", "Scanty", "Copious"] },
  { id: "hpi_wound_purulent", type: "hpi_symptom", category: "postoperative_wound", en: "Purulent wound discharge", fa: "ترشح چرکی زخم", colloquial_fa: "از بخیه چرک میاد، زخمم چرک کرده، مایع زرد یا سبز غلیظ خارج می‌شه، محل عمل عفونت کرده و چرک می‌کنه", modifiers: ["Yellow", "Green", "Thick", "Creamy", "Foul-smelling", "Scanty", "Copious"] },
  { id: "hpi_wound_odor", type: "hpi_symptom", category: "postoperative_wound", en: "Wound malodor", fa: "بوی بد زخم", colloquial_fa: "زخمم بوی بد می‌ده، جای بخیه بوی گند می‌ده، بوی عفونت میاد، پانسمانم بدبو شده", modifiers: ["Mild", "Severe", "Persistent", "Associated with discharge"] },
  { id: "hpi_wound_dehiscence", type: "hpi_symptom", category: "postoperative_wound", en: "Wound dehiscence", fa: "بازشدگی و گسیختگی زخم جراحی", colloquial_fa: "بخیه‌هام باز شده، جای عملم از هم باز شده، زخمم شکافته، لبه‌های زخم از هم فاصله گرفتن، محل بخیه دوباره باز شده", modifiers: ["Superficial", "Deep", "Partial", "Complete", "Acute", "With discharge"] },
  { id: "hpi_evisceration", type: "hpi_symptom", category: "postoperative_wound", en: "Evisceration", fa: "ایویسراسیون؛ بیرون‌زدگی احشاء از زخم", colloquial_fa: "روده یا داخل شکمم از جای بخیه بیرون زده، زخم شکمم باز شده و داخلش معلومه، چیزی از شکمم بیرون زده", modifiers: ["Partial", "Complete", "Visible bowel", "Acute postoperative"] },
  { id: "hpi_wound_bleeding", type: "hpi_symptom", category: "postoperative_wound", en: "Postoperative wound bleeding", fa: "خونریزی محل عمل", colloquial_fa: "جای عملم خون میاد، پانسمانم از خون خیس شده، از بخیه‌هام خونریزی می‌کنه، زخم جراحی‌ام خون می‌ده", modifiers: ["Active", "Oozing", "Intermittent", "Persistent", "Small volume", "Large volume"] },
  { id: "hpi_seroma", type: "hpi_symptom", category: "postoperative_wound", en: "Seroma", fa: "سروما؛ تجمع مایع سروزی زیر زخم", colloquial_fa: "زیر جای عملم آب جمع شده، یه برجستگی نرم زیر بخیه حس می‌کنم، محل عملم باد کرده انگار آب توشه، زیر پوستم مایع جمع شده", modifiers: ["Fluctuant", "Localized", "Non-infected appearance", "Progressive"] },
  { id: "hpi_wound_hematoma", type: "hpi_symptom", category: "postoperative_wound", en: "Postoperative hematoma", fa: "هماتوم پس از عمل", colloquial_fa: "زیر بخیه‌هام خون جمع شده، جای عملم کبود و متورم شده، یه توده سفت و دردناک زیر زخم پیدا شده", modifiers: ["Localized", "Expanding", "Painful", "Ecchymotic", "Fluctuant"] },
  { id: "hpi_wound_itching", type: "hpi_symptom", category: "postoperative_wound", en: "Wound pruritus", fa: "خارش محل زخم", colloquial_fa: "جای بخیه‌هام می‌خاره، دور زخمم خارش داره، پوست محل عملم می‌خاره، بخیه‌هام رو می‌خارونه", modifiers: ["Mild", "Severe", "With rash", "Without rash", "Healing-associated"] },
  { id: "hpi_wound_numbness", type: "hpi_symptom", category: "postoperative_wound", en: "Wound-site numbness", fa: "بی‌حسی محل جراحی", colloquial_fa: "اطراف بخیه‌هام بی‌حسه، پوست محل عملم حس نداره، دور زخمم خواب رفته، وقتی لمس می‌کنم چیزی حس نمی‌کنم", modifiers: ["Localized", "Persistent", "Improving", "Worsening"] },
  { id: "hpi_wound_skin_discoloration", type: "hpi_symptom", category: "postoperative_wound", en: "Wound skin discoloration", fa: "تغییر رنگ پوست محل زخم", colloquial_fa: "پوست دور بخیه سیاه شده، اطراف زخم بنفش شده، جای عملم رنگ عوض کرده، پوست محل زخم تیره شده", modifiers: ["Erythema", "Ecchymosis", "Dusky", "Pale", "Black", "Necrotic-appearing"] },

  // POSTOPERATIVE / DRAIN
  { id: "hpi_drain_output", type: "hpi_symptom", category: "postoperative_drain", en: "Drain output", fa: "میزان و ماهیت خروجی درن", colloquial_fa: "از لوله درنم مایع میاد، کیسه درنم پر می‌شه، از لوله‌ای که از شکمم بیرون اومده ترشح میاد، خروجی درنم زیاد یا کم شده", modifiers: ["Serous", "Serosanguineous", "Sanguineous", "Purulent", "Bilious", "Feculent", "Urine-like", "Clear", "Cloudy", "Increased volume", "Decreased volume", "No output"] },
  { id: "hpi_drain_increased_output", type: "hpi_symptom", category: "postoperative_drain", en: "Increased drain output", fa: "افزایش خروجی درن", colloquial_fa: "مایع درنم خیلی زیاد شده، کیسه درن زود پر می‌شه، نسبت به قبل خیلی بیشتر از لوله مایع میاد، درنم پرخروجی شده", modifiers: ["Sudden increase", "Gradual increase", "High-volume", "Persistent"] },
  { id: "hpi_drain_decreased_output", type: "hpi_symptom", category: "postoperative_drain", en: "Decreased drain output", fa: "کاهش خروجی درن", colloquial_fa: "مایع درنم کم شده، دیگه مثل قبل از لوله چیزی نمیاد، خروجی درن خیلی کمتر شده، کیسه درن خالی می‌مونه", modifiers: ["Gradual decrease", "Sudden decrease", "Minimal output"] },
  { id: "hpi_drain_no_output", type: "hpi_symptom", category: "postoperative_drain", en: "Absent drain output", fa: "قطع خروجی درن", colloquial_fa: "درنم دیگه چیزی نمی‌ده، لوله خشک شده، هیچ مایعی توی کیسه جمع نمی‌شه، خروجی درنم قطع شده", modifiers: ["Sudden", "Gradual", "With swelling", "Without swelling"] },
  { id: "hpi_drain_displacement", type: "hpi_symptom", category: "postoperative_drain", en: "Drain displacement / Dislodgement", fa: "جابجایی یا خارج شدن درن", colloquial_fa: "لوله درنم کشیده شده، درن از جاش دراومده، لوله از بدنم بیرون اومده، درنم شل شده، انگار لوله جابه‌جا شده", modifiers: ["Partial displacement", "Complete dislodgement", "Accidental traction"] },
  { id: "hpi_drain_blockage", type: "hpi_symptom", category: "postoperative_drain", en: "Drain blockage", fa: "گرفتگی درن", colloquial_fa: "لوله درنم گرفته، چیزی از درن خارج نمی‌شه، لوله بسته شده، مایع توی لوله حرکت نمی‌کنه، درنم کار نمی‌کنه", modifiers: ["Partial", "Complete", "Clot-related", "Debris-related"] },
  { id: "hpi_drain_site_leakage", type: "hpi_symptom", category: "postoperative_drain", en: "Leakage around drain site", fa: "نشت مایع از اطراف محل درن", colloquial_fa: "دور لوله درنم خیس می‌شه، از کنار درن مایع بیرون می‌زنه، پوست اطراف لوله ترشح می‌کنه، مایع از کنار درن راه می‌افته", modifiers: ["Serous", "Purulent", "Bilious", "Feculent", "Persistent", "Intermittent"] },
  { id: "hpi_drain_site_pain", type: "hpi_symptom", category: "postoperative_drain", en: "Drain-site pain", fa: "درد محل ورود درن", colloquial_fa: "جای لوله درنم درد می‌کنه، دور درن می‌سوزه، وقتی لوله تکون می‌خوره درد می‌گیره، محل ورود لوله تیر می‌کشه", modifiers: ["Movement-related", "Constant", "Localized", "Increasing"] },

  // POSTOPERATIVE / STOMA
  { id: "hpi_stoma_output", type: "hpi_symptom", category: "postoperative_stoma", en: "Stoma output", fa: "خروجی استوما", colloquial_fa: "از کیسه استومام مدفوع میاد، خروجی کیسه‌ام زیاده یا کمه، روده‌ام از شکمم دفع می‌کنه، محتویات توی کیسه جمع می‌شه", modifiers: ["Liquid", "Semi-formed", "Formed", "Watery", "Mucous", "Bloody", "Foul-smelling", "High-volume", "Low-volume"] },
  { id: "hpi_stoma_high_output", type: "hpi_symptom", category: "postoperative_stoma", en: "High-output stoma", fa: "استومای پرخروجی", colloquial_fa: "کیسه استومام خیلی زود پر می‌شه، مدام باید کیسه رو خالی کنم، خروجی استومام آبکی و خیلی زیاده، از استوما حجم زیادی مایع میاد", modifiers: ["Watery", "High-volume", "Frequent emptying", "Dehydration-associated"] },
  { id: "hpi_stoma_low_output", type: "hpi_symptom", category: "postoperative_stoma", en: "Low-output stoma", fa: "کاهش خروجی استوما", colloquial_fa: "از استومام خیلی کم دفع می‌شه، کیسه‌ام خالی می‌مونه، خروجی استوما کمتر شده، مثل قبل مدفوع از استوما نمیاد", modifiers: ["Reduced volume", "Reduced frequency", "New-onset"] },
  { id: "hpi_stoma_absent_output", type: "hpi_symptom", category: "postoperative_stoma", en: "Absent stoma output", fa: "قطع خروجی استوما", colloquial_fa: "استومام کار نمی‌کنه، از کیسه هیچ‌چی نمیاد، چند ساعته یا چند روزه دفع ندارم، خروجی استوما قطع شده، کیسه خالیه", modifiers: ["Acute", "Prolonged", "With abdominal pain", "With distension", "With vomiting"] },
  { id: "hpi_stoma_leakage", type: "hpi_symptom", category: "postoperative_stoma", en: "Stoma appliance leakage", fa: "نشت محتویات از اطراف کیسه استوما", colloquial_fa: "کیسه استومام نشتی داره، از کنار چسب کیسه مدفوع بیرون می‌زنه، دور استوما خیس می‌شه، چسب کیسه خوب نمی‌چسبه، لباسام کثیف می‌شه", modifiers: ["Intermittent", "Persistent", "Liquid output", "Poor appliance seal", "Peristomal skin irritation"] },
  { id: "hpi_stoma_prolapse", type: "hpi_symptom", category: "postoperative_stoma", en: "Stoma prolapse", fa: "پرولاپس استوما", colloquial_fa: "روده‌ام از شکمم بیشتر بیرون زده، استومام دراز شده، گوشت قرمز از شکمم بیرون زده، استوما بزرگ و بیرون‌زده شده", modifiers: ["Reducible", "Irreducible", "Intermittent", "Persistent", "Edematous"] },
  { id: "hpi_stoma_retraction", type: "hpi_symptom", category: "postoperative_stoma", en: "Stoma retraction", fa: "رتراکشن استوما", colloquial_fa: "استومام رفته داخل شکم، روده دیگه مثل قبل بیرون نیست، سوراخ استوما فرو رفته، استوما هم‌سطح یا پایین‌تر از پوست شده", modifiers: ["Mild", "Severe", "Below skin level", "Appliance leakage-associated"] },
  { id: "hpi_stoma_necrosis", type: "hpi_symptom", category: "postoperative_stoma", en: "Stoma ischemia / Necrosis", fa: "ایسکمی یا نکروز استوما", colloquial_fa: "استومام سیاه شده، رنگ روده عوض شده، استوما کبود یا تیره شده، قسمتی از روده از بین رفته به نظر می‌رسه", modifiers: ["Dusky", "Purple", "Black", "Mucosal", "Deep", "Progressive"] },
  { id: "hpi_stoma_bleeding", type: "hpi_symptom", category: "postoperative_stoma", en: "Stoma bleeding", fa: "خونریزی از استوما", colloquial_fa: "استومام خون می‌ده، از روده بیرون‌زده خون میاد، توی کیسه استوما خون جمع می‌شه، موقع تمیز کردن استوما خونریزی می‌کنه", modifiers: ["Minor contact bleeding", "Spontaneous", "Persistent", "Bright red", "Dark blood"] },
  { id: "hpi_stoma_peristomal_skin", type: "hpi_symptom", category: "postoperative_stoma", en: "Peristomal skin irritation", fa: "تحریک و آسیب پوست اطراف استوما", colloquial_fa: "دور استومام پوست قرمز و زخمی شده، پوست اطراف کیسه می‌سوزه، چسب کیسه پوستم رو کنده، دور استوما خارش و التهاب دارم", modifiers: ["Erythema", "Maceration", "Erosion", "Ulceration", "Painful", "Pruritic", "Moisture-associated"] },
  { id: "hpi_stoma_parastomal_bulge", type: "hpi_symptom", category: "postoperative_stoma", en: "Parastomal bulge / Hernia", fa: "برجستگی یا فتق اطراف استوما", colloquial_fa: "کنار استومام یه برجستگی زده، اطراف کیسه برآمده شده، دور روده بیرون‌زده شکمم ورم کرده، کنار استوما یه توده حس می‌کنم", modifiers: ["Reducible", "Irreducible", "Painful", "Painless", "Progressive"] },
  { id: "hpi_stoma_mucus", type: "hpi_symptom", category: "postoperative_stoma", en: "Mucus discharge from distal stoma / Rectal stump", fa: "ترشح موکوس از رکتوم یا استومای دیستال", colloquial_fa: "از مقعدم مخاط میاد، از قسمت پایین روده‌ام ترشح ژله‌ای خارج می‌شه، از روده‌ای که به کیسه وصل نیست لزجی میاد", modifiers: ["Clear", "White", "Yellow", "Bloody", "Scanty", "Copious"] },

  // POSTOPERATIVE / GENERAL COMPLICATIONS
  { id: "hpi_postop_fever", type: "hpi_symptom", category: "postoperative", en: "Postoperative fever", fa: "تب پس از عمل", colloquial_fa: "بعد از عمل تب کردم، بدنم بعد جراحی داغ شده، بعد از عمل لرز دارم، دمای بدنم بعد عمل بالا رفته", modifiers: ["Early postoperative", "Late postoperative", "Low-grade", "High-grade", "With chills", "Without chills"] },
  { id: "hpi_postop_nausea", type: "hpi_symptom", category: "postoperative", en: "Postoperative nausea", fa: "تهوع پس از عمل", colloquial_fa: "بعد از بیهوشی حالم به هم می‌خوره، بعد عمل حالت تهوع دارم، معده‌ام آشوبه، از وقتی عمل کردم دلم می‌خواد بالا بیارم", modifiers: ["Mild", "Severe", "Persistent", "Intermittent", "After anesthesia"] },
  { id: "hpi_postop_vomiting", type: "hpi_symptom", category: "postoperative", en: "Postoperative vomiting", fa: "استفراغ پس از عمل", colloquial_fa: "بعد از عمل بالا میارم، بعد از بیهوشی استفراغ کردم، هر چی می‌خورم برمی‌گرده، بعد از جراحی نمی‌تونم چیزی نگه دارم", modifiers: ["Bilious", "Non-bilious", "Bloody", "Recurrent", "Projectile", "Postprandial"] },
  { id: "hpi_postop_ileus", type: "hpi_symptom", category: "postoperative", en: "Postoperative ileus symptoms", fa: "علائم ایلئوس پس از عمل", colloquial_fa: "شکمم بعد عمل کار نمی‌کنه، باد شکمم خارج نمی‌شه، هنوز دفع نداشتم، شکمم باد کرده، بعد عمل روده‌هام راه نیفتاده", modifiers: ["Abdominal distension", "Nausea", "Vomiting", "Absent flatus", "Absent stool", "Delayed oral intake tolerance"] },
  { id: "hpi_delayed_flatus", type: "hpi_symptom", category: "postoperative", en: "Delayed passage of flatus", fa: "تأخیر در دفع گاز پس از عمل", colloquial_fa: "بعد عمل هنوز باد شکمم درنیومده، هنوز نتونستم گاز دفع کنم، شکمم کار نکرده، باد روده‌ام خارج نشده", modifiers: ["Early postoperative", "Prolonged", "With distension", "Without distension"] },
  { id: "hpi_delayed_stool", type: "hpi_symptom", category: "postoperative", en: "Delayed bowel movement after surgery", fa: "تأخیر در اجابت مزاج پس از عمل", colloquial_fa: "بعد عمل هنوز دستشویی نرفتم، هنوز مدفوع نکردم، شکمم باز نشده، از وقتی عمل کردم دفع نداشتم", modifiers: ["Early postoperative", "Prolonged", "With flatus", "Without flatus"] },
  { id: "hpi_postop_urinary_retention", type: "hpi_symptom", category: "postoperative", en: "Postoperative urinary retention", fa: "احتباس ادراری پس از عمل", colloquial_fa: "بعد از عمل جیشم نمیاد، از وقتی بیهوش شدم نتونستم ادرار کنم، مثانه‌ام پره ولی تخلیه نمی‌شه، بعد جراحی جیشم بند اومده", modifiers: ["Acute", "Painful", "Painless", "Catheterization-required"] },
  { id: "hpi_postop_dyspnea", type: "hpi_symptom", category: "postoperative", en: "Postoperative dyspnea", fa: "تنگی نفس پس از عمل", colloquial_fa: "بعد از عمل نفسم بالا نمیاد، بعد جراحی نفس کم میارم، موقع نفس کشیدن اذیت می‌شم، بعد بیهوشی احساس خفگی دارم", modifiers: ["At rest", "On exertion", "Acute", "Progressive", "With chest pain"] },
  { id: "hpi_postop_calf_pain", type: "hpi_symptom", category: "postoperative", en: "Postoperative calf pain", fa: "درد ساق پا پس از عمل", colloquial_fa: "بعد از عمل ساق پام درد گرفته، پشت ساق پام می‌کشه، یه پام بعد جراحی درد می‌کنه، موقع راه رفتن ساق پام تیر می‌کشه", modifiers: ["Unilateral", "Bilateral", "Swelling-associated", "Warmth-associated", "Tenderness-associated"] },
  { id: "hpi_postop_limb_swelling", type: "hpi_symptom", category: "postoperative", en: "Postoperative limb swelling", fa: "تورم اندام پس از عمل", colloquial_fa: "بعد عمل پام ورم کرده، یه دست یا پام باد کرده، ساق پام بزرگ‌تر شده، مچ پام پف کرده", modifiers: ["Unilateral", "Bilateral", "Pitting", "Non-pitting", "Painful", "Warm"] },
  { id: "hpi_postop_bleeding", type: "hpi_symptom", category: "postoperative", en: "Postoperative bleeding", fa: "خونریزی پس از عمل", colloquial_fa: "بعد عمل خونریزی دارم، از محل جراحی خون میاد، پانسمانم خونی می‌شه، خونریزی داخلی یا خارجی پیدا کردم", modifiers: ["External", "Suspected internal", "Early", "Delayed", "Minor", "Major"] },
  { id: "hpi_postop_pain_increase", type: "hpi_symptom", category: "postoperative", en: "Increasing postoperative pain", fa: "افزایش درد پس از عمل", colloquial_fa: "دردم به جای بهتر شدن بیشتر شده، هر روز بعد عمل درد بیشتری دارم، مسکن دیگه جواب نمی‌ده، جای عملم بدتر درد می‌کنه", modifiers: ["Progressive", "New-onset", "Analgesic-resistant", "Localized", "Diffuse"] },

  // VASCULAR / PERIPHERAL CIRCULATION
  { id: "hpi_varicose_veins", type: "hpi_symptom", category: "vascular", en: "Varicose veins symptoms", fa: "علائم واریس", colloquial_fa: "رگ‌های پام بیرون زده، رگ‌های پام برجسته و پیچ‌خورده شده، پام سنگین می‌شه، رگ پام باد کرده، آخر روز پام درد می‌گیره", modifiers: ["Visible dilated veins", "Heaviness", "Aching", "Edema", "Itching", "Unilateral", "Bilateral"] },
  { id: "hpi_leg_ulcer", type: "hpi_symptom", category: "vascular", en: "Lower limb ulcer", fa: "زخم اندام تحتانی", colloquial_fa: "پام زخم شده و خوب نمی‌شه، روی ساقم زخم دارم، زخم پام باز مونده، از زخم پام ترشح میاد، پوست پام سیاه و زخمی شده", modifiers: ["Venous-appearing", "Arterial-appearing", "Neuropathic-appearing", "Painful", "Painless", "Exudative", "Chronic"] },
  { id: "hpi_cold_sweaty_limb", type: "hpi_symptom", category: "vascular", en: "Cold and pale limb", fa: "اندام سرد و رنگ‌پریده", colloquial_fa: "دستم یا پام یخ کرده و رنگش پریده، یه دفعه پام سرد و سفید شده، انگشتام سرد و بی‌رنگ شدن", modifiers: ["Acute", "Unilateral", "Pallor", "Pain-associated", "Paresthesia-associated"] },
  { id: "hpi_raynaud_symptoms", type: "hpi_symptom", category: "vascular", en: "Raynaud phenomenon symptoms", fa: "علائم پدیده رینود", colloquial_fa: "انگشتام با سرما سفید می‌شن بعد کبود و قرمز می‌شن، وقتی دستم سرد می‌شه انگشتام بی‌حس می‌شن، رنگ انگشتام عوض می‌شه", modifiers: ["White phase", "Blue phase", "Red phase", "Cold-triggered", "Stress-triggered", "Painful"] },

  // ENT / EYES / ORAL
  { id: "hpi_sore_throat", type: "hpi_symptom", category: "ent", en: "Sore throat", fa: "گلودرد", colloquial_fa: "گلوی من درد می‌کنه، گلوم می‌سوزه، موقع قورت دادن گلو درد دارم، ته گلومم درد می‌کنه، گلومم خشکه و درد می‌کنه", modifiers: ["Acute", "Chronic", "Unilateral", "Bilateral", "Odynophagia-associated"] },
  { id: "hpi_rhinorrhea", type: "hpi_symptom", category: "ent", en: "Rhinorrhea", fa: "رینوره؛ آبریزش بینی", colloquial_fa: "بینی‌ام آب میاد، دماغم راه افتاده، آب از بینیم می‌ریزه، مدام فین می‌کنم، بینی‌ام ترشح داره", modifiers: ["Clear", "Watery", "Mucoid", "Purulent", "Unilateral", "Bilateral"] },
  { id: "hpi_nasal_congestion", type: "hpi_symptom", category: "ent", en: "Nasal congestion", fa: "گرفتگی بینی", colloquial_fa: "بینیم کیپ شده، نمی‌تونم از بینی نفس بکشم، دماغم گرفته، راه بینیم بسته شده، بینی‌ام پره", modifiers: ["Unilateral", "Bilateral", "Intermittent", "Persistent"] },
  { id: "hpi_epistaxis", type: "hpi_symptom", category: "ent", en: "Epistaxis", fa: "اپیستاکسی؛ خونریزی بینی", colloquial_fa: "دماغم خون میاد، خون دماغ شدم، از بینیم خون می‌ریزه، بینی‌ام خونریزی می‌کنه", modifiers: ["Anterior", "Posterior", "Unilateral", "Bilateral", "Spontaneous", "Traumatic", "Recurrent"] },
  { id: "hpi_otalgia", type: "hpi_symptom", category: "ent", en: "Otalgia", fa: "اوتالژی؛ گوش‌درد", colloquial_fa: "گوشم درد می‌کنه، توی گوشم تیر می‌کشه، گوشم می‌سوزه، داخل گوشم فشار حس می‌کنم", modifiers: ["Right", "Left", "Bilateral", "Acute", "Chronic", "Referred"] },
  { id: "hpi_otorrhea", type: "hpi_symptom", category: "ent", en: "Otorrhea", fa: "اوتوره؛ ترشح گوش", colloquial_fa: "از گوشم مایع میاد، گوشم چرک می‌کنه، گوشم آب می‌اندازه، از گوشم خون یا ترشح خارج می‌شه", modifiers: ["Serous", "Purulent", "Bloody", "Clear", "Foul-smelling", "Unilateral", "Bilateral"] },
  { id: "hpi_hearing_loss", type: "hpi_symptom", category: "ent", en: "Hearing loss", fa: "کاهش شنوایی", colloquial_fa: "گوشم سنگین شده، خوب نمی‌شنوم، صداها رو ضعیف می‌شنوم، باید بلندتر حرف بزنن تا بشنوم، یه گوشم نمی‌شنوه", modifiers: ["Unilateral", "Bilateral", "Sudden", "Gradual", "Conductive-like", "Sensorineural-like"] },
  { id: "hpi_tinnitus", type: "hpi_symptom", category: "ent", en: "Tinnitus", fa: "وزوز گوش", colloquial_fa: "توی گوشم سوت می‌کشه، صدای زنگ می‌شنوم، گوشم وزوز می‌کنه، صدای زنگ ممتد دارم، توی گوشم صدای زنبور میاد", modifiers: ["Unilateral", "Bilateral", "Pulsatile", "Non-pulsatile", "Continuous", "Intermittent"] },
  { id: "hpi_ear_fullness", type: "hpi_symptom", category: "ent", en: "Ear fullness", fa: "احساس پری و گرفتگی گوش", colloquial_fa: "گوشم گرفته، انگار توی گوشم پنبه گذاشتن، گوشم کیپ شده، احساس فشار و پری گوش دارم، صداها خفه می‌شن", modifiers: ["Unilateral", "Bilateral", "Intermittent", "Persistent"] },
  { id: "hpi_anosmia", type: "hpi_symptom", category: "ent", en: "Anosmia", fa: "آنوسمی؛ فقدان حس بویایی", colloquial_fa: "بوها رو حس نمی‌کنم، بوی غذا رو نمی‌فهمم، حس بویاییم از بین رفته، عطر رو بو نمی‌کنم", modifiers: ["Complete", "Partial", "Sudden", "Gradual", "Unilateral"] },
  { id: "hpi_hyposmia", type: "hpi_symptom", category: "ent", en: "Hyposmia", fa: "هیپوسمی؛ کاهش حس بویایی", colloquial_fa: "بوها رو ضعیف حس می‌کنم، باید نزدیک بینی‌ام باشه تا بو رو بفهمم، حس بویاییم کم شده", modifiers: ["Mild", "Moderate", "Severe", "Acute", "Chronic"] },
  { id: "hpi_dysgeusia", type: "hpi_symptom", category: "ent", en: "Dysgeusia", fa: "دیس‌گوزی؛ اختلال حس چشایی", colloquial_fa: "مزه دهنم عوض شده، همه چی تلخ می‌شه، دهنم مزه فلز می‌ده، مزه غذاها رو درست نمی‌فهمم، مزه بد توی دهنمه", modifiers: ["Metallic", "Bitter", "Sour", "Altered taste", "Persistent"] },
  { id: "hpi_oral_ulcer", type: "hpi_symptom", category: "ent", en: "Oral ulcer", fa: "زخم دهانی و آفت", colloquial_fa: "توی دهنم آفت زده، زبونم زخم شده، داخل لپم زخم شده، یه دونه سفید دردناک توی دهنم دراومده، موقع غذا خوردن می‌سوزه", modifiers: ["Single", "Multiple", "Painful", "Painless", "Recurrent", "Traumatic"] },
  { id: "hpi_gingival_bleeding", type: "hpi_symptom", category: "ent", en: "Gingival bleeding", fa: "خونریزی لثه", colloquial_fa: "لثه‌ام خون میاد، موقع مسواک خون می‌بینم، لثه‌هام خونریزی می‌کنه، بی‌دلیل از لثه‌ام خون میاد", modifiers: ["Spontaneous", "Brushing-related", "Localized", "Generalized"] },
  { id: "hpi_eye_pain", type: "hpi_symptom", category: "ent", en: "Eye pain", fa: "درد چشم", colloquial_fa: "چشمم درد می‌کنه، پشت چشمم درد دارم، توی چشمم تیر می‌کشه، چشمم می‌سوزه، با حرکت چشم درد می‌گیره", modifiers: ["Unilateral", "Bilateral", "Superficial", "Deep", "Movement-related", "Photophobia-associated"] },
  { id: "hpi_eye_redness", type: "hpi_symptom", category: "ent", en: "Red eye", fa: "قرمزی چشم", colloquial_fa: "چشمم قرمز شده، سفیدی چشمم خون افتاده، چشمم سرخ شده، رگ‌های چشمم قرمز شدن", modifiers: ["Unilateral", "Bilateral", "Diffuse", "Localized", "Painful", "Painless"] },
  { id: "hpi_eye_discharge", type: "hpi_symptom", category: "ent", en: "Ocular discharge", fa: "ترشح چشم", colloquial_fa: "چشمم چرک می‌کنه، صبح پلکام به هم می‌چسبه، از چشمم آب یا چرک میاد، گوشه چشمم کثیف می‌شه", modifiers: ["Watery", "Mucous", "Purulent", "Muco-purulent", "Unilateral", "Bilateral"] },
  { id: "hpi_tearing", type: "hpi_symptom", category: "ent", en: "Epiphora / Excessive tearing", fa: "اشک‌ریزش", colloquial_fa: "چشمم اشک می‌ریزه، مدام اشک از چشمم میاد، بدون گریه چشمم خیس می‌شه، چشمم آب می‌ندازه", modifiers: ["Unilateral", "Bilateral", "Intermittent", "Persistent"] },

  // SKIN / SOFT TISSUE
  { id: "hpi_rash", type: "hpi_symptom", category: "dermatologic", en: "Skin rash", fa: "راش پوستی و بثورات", colloquial_fa: "پوستم جوش زده، دونه‌دونه شده، لکه روی پوستم افتاده، بدنم دونه زده، پوستم قرمز و ملتهب شده، کهیر زدم", modifiers: ["Macular", "Papular", "Maculopapular", "Vesicular", "Pustular", "Urticarial", "Petechial", "Purpuric", "Localized", "Generalized"] },
  { id: "hpi_urticaria", type: "hpi_symptom", category: "dermatologic", en: "Urticaria / Hives", fa: "کهیر", colloquial_fa: "کهیر زدم، روی پوستم برجستگی خارش‌دار زده، دونه‌های بادکرده میاد و می‌ره، پوستم مثل نیش حشره برجسته شده", modifiers: ["Acute", "Chronic", "Localized", "Generalized", "Migratory", "Pruritic"] },
  { id: "hpi_skin_ulcer", type: "hpi_symptom", category: "dermatologic", en: "Skin ulcer", fa: "اولسر پوستی", colloquial_fa: "پوستم زخم باز شده، یه قسمت از پوستم کنده شده، زخم عمیق دارم، زخمم خوب نمی‌شه، از پوست ترشح میاد", modifiers: ["Superficial", "Deep", "Painful", "Painless", "Necrotic", "Exudative", "Chronic"] },
  { id: "hpi_skin_lump", type: "hpi_symptom", category: "dermatologic", en: "Subcutaneous lump", fa: "توده زیرپوستی", colloquial_fa: "زیر پوستم یه گلوله حس می‌کنم، یه دونه سفت زیر پوستم دراومده، یه برجستگی زیر پوست دارم، یه توده زیرپوستی پیدا کردم", modifiers: ["Soft", "Firm", "Hard", "Mobile", "Fixed", "Painful", "Painless", "Growing"] },
  { id: "hpi_skin_color_change", type: "hpi_symptom", category: "dermatologic", en: "Skin color change", fa: "تغییر رنگ پوست", colloquial_fa: "پوستم تیره شده، یه جاهای پوستم سفید شده، رنگ پوستم عوض شده، لکه‌های قهوه‌ای یا سفید پیدا کردم، پوستم کبود شده", modifiers: ["Hyperpigmentation", "Hypopigmentation", "Erythema", "Cyanosis", "Pallor", "Localized", "Generalized"] },
  { id: "hpi_hair_loss", type: "hpi_symptom", category: "dermatologic", en: "Hair loss / Alopecia", fa: "ریزش مو و آلوپسی", colloquial_fa: "موهام می‌ریزه، موهام کم‌پشت شده، موقع حمام کلی مو می‌ریزه، جلوی سرم خالی شده، یه قسمت از سرم کچل شده", modifiers: ["Diffuse", "Patchy", "Androgenic pattern", "Scarring", "Non-scarring", "Acute", "Chronic"] },
  { id: "hpi_nail_change", type: "hpi_symptom", category: "dermatologic", en: "Nail changes", fa: "تغییرات ناخن", colloquial_fa: "ناخنام تغییر شکل دادن، ناخنام شکننده شدن، ناخن‌هام رنگ عوض کردن، ناخن‌هام از بستر جدا می‌شن، روی ناخنم خط افتاده", modifiers: ["Discoloration", "Brittleness", "Clubbing", "Pitting", "Onycholysis", "Thickening"] },

  // ENDOCRINE / METABOLIC
  { id: "hpi_heat_intolerance", type: "hpi_symptom", category: "endocrine", en: "Heat intolerance", fa: "عدم تحمل گرما", colloquial_fa: "گرما اذیتم می‌کنه، زود گرمم می‌شه، بقیه سردشونه ولی من گرممه، زیاد عرق می‌کنم، تحمل هوای گرم رو ندارم", modifiers: ["Persistent", "New-onset", "Associated with sweating", "Associated with palpitations"] },
  { id: "hpi_cold_intolerance", type: "hpi_symptom", category: "endocrine", en: "Cold intolerance", fa: "عدم تحمل سرما", colloquial_fa: "همیشه سردمه، بقیه گرمشونه ولی من می‌لرزم، دست و پام یخ می‌کنه، تحمل سرما رو ندارم", modifiers: ["Persistent", "New-onset", "Associated with fatigue"] },
  { id: "hpi_polyphagia", type: "hpi_symptom", category: "endocrine", en: "Polyphagia", fa: "پلی‌فاژی؛ گرسنگی و افزایش اشتها", colloquial_fa: "هر چی می‌خورم سیر نمی‌شم، دائم گرسنه‌ام، اشتهایم خیلی زیاد شده، مدام دلم خوراکی می‌خواد", modifiers: ["Persistent", "Associated with weight loss", "Associated with weight gain"] },
  { id: "hpi_polydipsia", type: "hpi_symptom", category: "endocrine", en: "Polydipsia", fa: "پلی‌دیپسی؛ تشنگی بیش از حد", colloquial_fa: "آب از گلوم پایین نمی‌ره بس که تشنه‌ام، هر چی آب می‌خورم باز تشنه‌ام، دهنم همیشه خشکه، مدام دنبال آبم", modifiers: ["Persistent", "Nocturnal", "Associated with polyuria"] },
  { id: "hpi_hypoglycemia_symptoms", type: "hpi_symptom", category: "endocrine", en: "Hypoglycemic symptoms", fa: "علائم افت قند خون", colloquial_fa: "قندم می‌افته، یه دفعه ضعف می‌کنم، عرق سرد می‌کنم، دستم می‌لرزه، گرسنگی شدید می‌گیرم، چشمام سیاهی می‌ره، حالم بد می‌شه تا شیرینی بخورم", modifiers: ["Sweating", "Tremor", "Hunger", "Palpitations", "Confusion", "Visual disturbance", "Relieved by glucose"] },
  { id: "hpi_hyperglycemia_symptoms", type: "hpi_symptom", category: "endocrine", en: "Hyperglycemic symptoms", fa: "علائم افزایش قند خون", colloquial_fa: "خیلی تشنه‌ام، زیاد جیش می‌کنم، دهنم خشک شده، خسته‌ام، تاری دید دارم، وزنم کم شده", modifiers: ["Polyuria", "Polydipsia", "Polyphagia", "Fatigue", "Blurred vision", "Weight loss"] },

  // HEMATOLOGIC
  { id: "hpi_easy_bruising", type: "hpi_symptom", category: "hematologic", en: "Easy bruising", fa: "کبودی آسان", colloquial_fa: "با یه ضربه کوچیک کبود می‌شم، بی‌دلیل بدنم کبود می‌شه، زود خون‌مردگی می‌گیرم، با فشار کم پوستم کبود می‌شه", modifiers: ["Spontaneous", "Minor trauma-related", "Multiple sites", "Progressive"] },
  { id: "hpi_easy_bleeding", type: "hpi_symptom", category: "hematologic", en: "Easy bleeding", fa: "تمایل به خونریزی", colloquial_fa: "با یه خراش کوچیک خونم بند نمیاد، زود خونریزی می‌کنم، لثه‌ام بی‌دلیل خون میاد، از دماغم زود خون میاد، زخمم دیر بند میاد", modifiers: ["Mucosal", "Cutaneous", "Prolonged bleeding", "Spontaneous", "Post-procedural"] },
  { id: "hpi_pallor", type: "hpi_symptom", category: "hematologic", en: "Pallor", fa: "رنگ‌پریدگی", colloquial_fa: "رنگم پریده، صورتم سفید شده، لبام بی‌رنگ شده، همه می‌گن رنگت پریده، مثل قبل سرحال و گلگون نیستم", modifiers: ["Facial", "Conjunctival", "Palmar", "Generalized", "Acute", "Chronic"] },
  { id: "hpi_lymph_node_swelling", type: "hpi_symptom", category: "hematologic", en: "Lymphadenopathy / Enlarged lymph nodes", fa: "لنفادنوپاتی؛ بزرگ شدن غدد لنفاوی", colloquial_fa: "غده‌ام ورم کرده، زیر بغلم یه گلوله حس می‌کنم، زیر فکم غده زده، کشاله رانم یه توده پیدا شده، غدد گردنم بزرگ شده", modifiers: ["Cervical", "Supraclavicular", "Axillary", "Inguinal", "Localized", "Generalized", "Painful", "Painless", "Mobile", "Fixed"] },
  { id: "hpi_bone_pain_general", type: "hpi_symptom", category: "hematologic", en: "Bone pain", fa: "درد استخوان", colloquial_fa: "استخونم درد می‌کنه، عمق استخونم درد داره، مغز استخونم تیر می‌کشه، استخون‌درد شدید دارم", modifiers: ["Localized", "Diffuse", "Nocturnal", "Persistent", "Movement-related"] },

  // PSYCHIATRIC / AFFECTIVE SYMPTOMS RELEVANT TO HPI
  { id: "hpi_anxiety", type: "hpi_symptom", category: "psychiatric", en: "Anxiety", fa: "اضطراب", colloquial_fa: "دلشوره دارم، استرس دارم، دلم شور می‌زنه، بی‌قرارم، یه ترس مبهم دارم، آروم و قرار ندارم، مدام نگرانم", modifiers: ["Mild", "Moderate", "Severe", "Persistent", "Episodic", "Situational"] },
  { id: "hpi_panic", type: "hpi_symptom", category: "psychiatric", en: "Panic attack symptoms", fa: "علائم حمله پانیک", colloquial_fa: "یه دفعه حس می‌کنم دارم می‌میرم، قلبم می‌زنه بیرون، نفسم بند میاد، بدنم می‌لرزه، حس خفگی و ترس شدید می‌گیرم", modifiers: ["Sudden onset", "Peak within minutes", "Palpitations", "Dyspnea", "Chest discomfort", "Fear of dying"] },
  { id: "hpi_depressed_mood", type: "hpi_symptom", category: "psychiatric", en: "Depressed mood", fa: "خلق افسرده", colloquial_fa: "حوصله هیچ‌چی رو ندارم، دلم گرفته، غمگینم، همیشه ناراحتم، هیچ چیزی خوشحالم نمی‌کنه، بی‌انگیزه‌ام", modifiers: ["Persistent", "Episodic", "Anhedonia-associated", "Morning-predominant", "Evening-predominant"] },
  { id: "hpi_agitation", type: "hpi_symptom", category: "psychiatric", en: "Agitation / Restlessness", fa: "بی‌قراری و آژیتاسیون", colloquial_fa: "قرار ندارم، آروم و قرار ندارم، نمی‌تونم یه جا بشینم، مدام راه می‌رم، عصبی و بی‌تابم، خودم رو کنترل نمی‌کنم", modifiers: ["Psychomotor", "Mild", "Severe", "Acute", "Fluctuating"] },
  { id: "hpi_irritability", type: "hpi_symptom", category: "psychiatric", en: "Irritability", fa: "تحریک‌پذیری و زودرنجی", colloquial_fa: "زود عصبانی می‌شم، اعصابم خورده، با کوچک‌ترین چیزی از کوره درمی‌رم، تحملم کم شده، زود از کوره در می‌رم", modifiers: ["New-onset", "Persistent", "Episodic", "Sleep-associated"] },

  // ADDITIONAL SURGICAL / ABDOMINAL WALL / POST-PROCEDURAL
  { id: "hpi_groin_pain", type: "hpi_symptom", category: "surgical", en: "Groin pain", fa: "درد کشاله ران", colloquial_fa: "کشاله رانم درد می‌کنه، بین شکم و پام درد دارم، نزدیک بیضه یا رانم تیر می‌کشه، محل فتقم درد می‌کنه", modifiers: ["Right", "Left", "Bilateral", "Movement-related", "Cough-related", "Radiating"] },
  { id: "hpi_abdominal_wall_pain", type: "hpi_symptom", category: "surgical", en: "Abdominal wall pain", fa: "درد دیواره شکم", colloquial_fa: "پوست و عضله شکمم درد می‌کنه، وقتی شکمم رو سفت می‌کنم درد می‌گیره، با حرکت تنه درد دارم، روی دیواره شکمم یه نقطه دردناک هست", modifiers: ["Localized", "Superficial", "Movement-related", "Palpation-sensitive"] },
  { id: "hpi_postoperative_mass", type: "hpi_symptom", category: "postoperative", en: "Postoperative mass / Lump", fa: "توده یا برجستگی پس از عمل", colloquial_fa: "زیر جای بخیه یه گلوله دراومده، محل عملم برجسته شده، یه توده زیر پوست کنار زخم حس می‌کنم، جای جراحی باد کرده", modifiers: ["Soft", "Firm", "Fluctuant", "Painful", "Painless", "Progressive"] },
  { id: "hpi_catheter_leakage", type: "hpi_symptom", category: "postoperative", en: "Urinary catheter leakage", fa: "نشت ادرار از اطراف سوند", colloquial_fa: "ادرار از کنار سوند می‌ریزه، دور لوله سوند خیس می‌شه، با اینکه سوند دارم باز از کنار آلت جیش میاد، کیسه سوند درست پر نمی‌شه", modifiers: ["Intermittent", "Persistent", "With bladder spasms", "With reduced catheter output"] },
  { id: "hpi_catheter_blockage", type: "hpi_symptom", category: "postoperative", en: "Urinary catheter blockage", fa: "گرفتگی سوند ادراری", colloquial_fa: "سوند ادرار نمی‌ده، لوله سوند گرفته، کیسه خالی مونده، ادرار از سوند خارج نمی‌شه، زیر دلم با وجود سوند پر و دردناک شده", modifiers: ["Partial", "Complete", "Clot-related", "Debris-related", "With suprapubic pain"] },
  { id: "hpi_catheter_discomfort", type: "hpi_symptom", category: "postoperative", en: "Urinary catheter discomfort", fa: "ناراحتی ناشی از سوند", colloquial_fa: "سوند اذیتم می‌کنه، لوله توی مجرام درد می‌کنه، با حرکت لوله می‌سوزه، حس می‌کنم سوند داره می‌کشه", modifiers: ["Urethral pain", "Bladder spasm", "Movement-related", "Persistent"] },
  { id: "hpi_postprocedural_dysphagia", type: "hpi_symptom", category: "postoperative", en: "Post-procedural dysphagia", fa: "اختلال بلع پس از اقدام پزشکی یا جراحی", colloquial_fa: "بعد از لوله‌گذاری یا عمل گلوم درد می‌کنه، بعد از بیهوشی قورت دادن برام سخته، بعد از گذاشتن لوله صدام گرفته و بلع سخت شده", modifiers: ["Mild", "Severe", "Solids", "Liquids", "Transient", "Persistent"] },
  { id: "hpi_postprocedural_hoarseness", type: "hpi_symptom", category: "postoperative", en: "Post-intubation hoarseness", fa: "گرفتگی صدا پس از لوله‌گذاری", colloquial_fa: "بعد از بیهوشی صدام گرفته، از وقتی لوله تنفسی داشتم صدام خش‌دار شده، بعد عمل نمی‌تونم درست حرف بزنم", modifiers: ["Transient", "Persistent", "Mild", "Severe"] },
  { id: "hpi_postoperative_hematochezia", type: "hpi_symptom", category: "postoperative", en: "Postoperative rectal bleeding", fa: "خونریزی رکتال پس از عمل", colloquial_fa: "بعد از عمل از مقعدم خون میاد، بعد جراحی موقع دفع خون می‌بینم، از روده‌ام خونریزی می‌کنه", modifiers: ["Bright red", "Dark red", "With stool", "Without stool", "Scanty", "Heavy"] },
  { id: "hpi_postoperative_vaginal_bleeding", type: "hpi_symptom", category: "postoperative", en: "Postoperative vaginal bleeding", fa: "خونریزی واژینال پس از عمل", colloquial_fa: "بعد از عمل زنان خونریزی دارم، از واژنم خون میاد، بعد جراحی لکه‌بینی دارم، خونریزی‌ام بیشتر شده", modifiers: ["Spotting", "Light", "Heavy", "Persistent", "Increasing"] },
  { id: "hpi_postoperative_urine_change", type: "hpi_symptom", category: "postoperative", en: "Postoperative urine change", fa: "تغییر رنگ یا ویژگی ادرار پس از عمل", colloquial_fa: "بعد از عمل رنگ جیشم عوض شده، ادرارم خونی یا تیره شده، ادرارم کدر شده، ادرارم بوی بد می‌ده", modifiers: ["Hematuria", "Dark", "Cloudy", "Foul-smelling", "Reduced volume"] }
